def _player_fleet_registry(state:dict)->dict:
    er=state.get("engine_runtime") or {};reg=er.get("player_fleet_registry") or {}
    if not isinstance(reg,dict):raise EngineError("PLAYER_FLEET_REGISTRY_INVALID")
    if reg and reg.get("schema")!=PLAYER_FLEET_REGISTRY_SCHEMA:raise EngineError("PLAYER_FLEET_REGISTRY_SCHEMA_INVALID")
    fleets=reg.get("fleets") or {}
    if not isinstance(fleets,dict):raise EngineError("PLAYER_FLEET_REGISTRY_FLEETS_INVALID")
    return reg


def _maintenance_runtime(state:dict,create:bool=False)->dict:
    er=state.setdefault("engine_runtime",{}) if create else (state.get("engine_runtime") or {})
    mr=er.get("maintenance_runtime")
    if mr is None:
        if not create:return {"schema":MAINTENANCE_RUNTIME_SCHEMA,"repair_queue":[],"medical_queue":[],"completed_jobs":{},"blocked_jobs":{},"pending_replenishment":[]}
        mr={"schema":MAINTENANCE_RUNTIME_SCHEMA,"repair_queue":[],"medical_queue":[],"completed_jobs":{},"blocked_jobs":{},"pending_replenishment":[]};er["maintenance_runtime"]=mr
    if not isinstance(mr,dict) or mr.get("schema")!=MAINTENANCE_RUNTIME_SCHEMA:raise EngineError("MAINTENANCE_RUNTIME_INVALID")
    for k,default in (("repair_queue",[]),("medical_queue",[]),("completed_jobs",{}),("blocked_jobs",{}),("pending_replenishment",[])):
        if k not in mr and create:mr[k]=copy.deepcopy(default)
    if not isinstance(mr.get("repair_queue",[]),list) or not isinstance(mr.get("medical_queue",[]),list):raise EngineError("MAINTENANCE_QUEUE_INVALID")
    if not isinstance(mr.get("completed_jobs",{}),dict) or not isinstance(mr.get("blocked_jobs",{}),dict):raise EngineError("MAINTENANCE_JOB_INDEX_INVALID")
    if not isinstance(mr.get("pending_replenishment",[]),list):raise EngineError("REPLENISHMENT_PENDING_INVALID")
    return mr


def _maintenance_job_exists(mr:dict,job_id:str)->bool:
    if job_id in (mr.get("completed_jobs") or {}) or job_id in (mr.get("blocked_jobs") or {}):return True
    return any(isinstance(x,dict) and str(x.get("job_id"))==job_id for q in ("repair_queue","medical_queue") for x in (mr.get(q) or []))


def _maintenance_validate_action(state:dict,kind:str,action:dict)->dict:
    if not isinstance(action,dict):raise EngineError("MAINTENANCE_ACTION_NOT_OBJECT")
    op=str(action.get("op") or "").strip();path=str(action.get("path") or "").strip()
    if op not in {"restore_pct_100","restore_from_path","set_status","clear_flag"}:raise EngineError(f"MAINTENANCE_ACTION_OP_INVALID:{op}")
    if not path.startswith(("STATE.","state:")):raise EngineError(f"MAINTENANCE_ACTION_STATE_PATH_REQUIRED:{path}")
    lp=path.lower()
    if any(tok in lp for tok in MAINTENANCE_SENSITIVE_PATH_TOKENS):raise EngineError(f"MAINTENANCE_ACTION_SENSITIVE_PATH:{path}")
    if not any(lp.startswith(prefix+root) for prefix in ('state.','state:') for root in ("voyager_fleet","jinchuan_fleet","shadow_fleet","world_state_overrides")):raise EngineError(f"MAINTENANCE_ACTION_ROOT_FORBIDDEN:{path}")
    try:before=copy.deepcopy(get_by_path(state,path[6:]))
    except KeyError:raise EngineError(f"MAINTENANCE_ACTION_PATH_MISSING:{path}")
    out={"op":op,"path":path,"expected_before":before}
    if op=="restore_pct_100":
        if not isinstance(before,(int,float)) or isinstance(before,bool) or not (0<=float(before)<=100):raise EngineError(f"MAINTENANCE_RESTORE_PCT_INVALID:{path}")
        if not any(tok in lp for tok in ("condition","integrity","complete","health","damage","repair")):raise EngineError(f"MAINTENANCE_RESTORE_PCT_SEMANTIC_PATH:{path}")
        out["value"]=100 if isinstance(before,int) else 100.0
    elif op=="restore_from_path":
        src=str(action.get("source_path") or "").strip()
        if not src.startswith(("STATE.","state:")):raise EngineError("MAINTENANCE_RESTORE_SOURCE_PATH_REQUIRED")
        try:value=copy.deepcopy(get_by_path(state,src[6:]))
        except KeyError:raise EngineError(f"MAINTENANCE_RESTORE_SOURCE_MISSING:{src}")
        if isinstance(before,(dict,list)) or isinstance(value,(dict,list)) or type(before) is not type(value):raise EngineError("MAINTENANCE_RESTORE_TYPE_MISMATCH")
        out["source_path"]=src;out["source_value_at_enqueue"]=value;out["value"]=value
    elif op=="set_status":
        value=action.get("value")
        if not isinstance(value,str) or not value.strip() or len(value)>120:raise EngineError("MAINTENANCE_STATUS_VALUE_INVALID")
        if not (lp.endswith("status") or lp.endswith("_status") or ".status" in lp):raise EngineError(f"MAINTENANCE_STATUS_PATH_INVALID:{path}")
        out["value"]=value
    else:
        if not isinstance(before,bool):raise EngineError(f"MAINTENANCE_CLEAR_FLAG_BOOL_REQUIRED:{path}")
        out["value"]=False
    if kind=="medical" and not any(tok in lp for tok in ("medical","health","treat","recover","wound","injur","status")):raise EngineError(f"MEDICAL_ACTION_PATH_NOT_MEDICAL:{path}")
    return out


def _normalize_maintenance_job(state:dict,raw:dict,now:dt.datetime,source_battle_id:Optional[str]=None)->dict:
    if not isinstance(raw,dict):raise EngineError("MAINTENANCE_JOB_NOT_OBJECT")
    forbidden={"cost","gold","grey","gray","medical_kit","medkit","supply_cost","purchase"}
    if any(k in raw for k in forbidden):raise EngineError("MAINTENANCE_JOB_FORBIDDEN_COST_OR_SUPPLY_FIELD")
    kind=str(raw.get("kind") or "").strip();job_id=str(raw.get("job_id") or "").strip()
    if kind not in MAINTENANCE_KINDS:raise EngineError(f"MAINTENANCE_KIND_INVALID:{kind}")
    if not job_id or len(job_id)>160:raise EngineError("MAINTENANCE_JOB_ID_INVALID")
    start=parse_iso(raw.get("started_at")) if raw.get("started_at") else now;complete=parse_iso(raw.get("complete_at"))
    if start is None or complete is None:raise EngineError(f"MAINTENANCE_JOB_TIME_REQUIRED:{job_id}")
    if start!=now:raise EngineError(f"MAINTENANCE_JOB_START_MUST_EQUAL_CURRENT_GAME_TIME:{job_id}")
    delta=(complete-start).total_seconds()
    if delta<=0 or delta>MAINTENANCE_MAX_SECONDS:raise EngineError(f"MAINTENANCE_JOB_DURATION_INVALID:{job_id}:{int(delta)}")
    fleet_id=str(raw.get("fleet_id") or "").strip() or None
    if fleet_id:
        fleets=(_player_fleet_registry(state).get("fleets") or {})
        if fleet_id not in fleets:raise EngineError(f"MAINTENANCE_FLEET_UNKNOWN:{fleet_id}")
    actions=[_maintenance_validate_action(state,kind,a) for a in (raw.get("completion_actions") or [])]
    job={"schema":MAINTENANCE_JOB_SCHEMA,"job_id":job_id,"kind":kind,"status":"active","fleet_id":fleet_id,"target_id":raw.get("target_id"),"asset_class":raw.get("asset_class"),"started_at":start.strftime("%Y-%m-%dT%H:%M:%S"),"complete_at":complete.strftime("%Y-%m-%dT%H:%M:%S"),"completion_actions":actions,"source_battle_id":source_battle_id or raw.get("source_battle_id"),"source_event_id":raw.get("source_event_id"),"severity":raw.get("severity"),"tracked_count":int(raw.get("tracked_count",0) or 0),"policy":{"max_days":30,"extra_gold_cost":False,"auto_medkit_consumption":False,"parallel_queue":True}}
    if job["tracked_count"]<0:raise EngineError("MAINTENANCE_TRACKED_COUNT_NEGATIVE")
    return job


def _enqueue_maintenance_jobs(state:dict,jobs:list,now:dt.datetime,source_battle_id:Optional[str]=None)->list:
    if not isinstance(jobs,list):raise EngineError("MAINTENANCE_JOBS_LIST_REQUIRED")
    mr=_maintenance_runtime(state,create=True);added=[]
    for raw in jobs:
        job=_normalize_maintenance_job(state,raw,now,source_battle_id)
        if _maintenance_job_exists(mr,job["job_id"]):raise EngineError(f"MAINTENANCE_JOB_DUPLICATE:{job['job_id']}")
        mr["repair_queue" if job["kind"]=="repair" else "medical_queue"].append(job);added.append(copy.deepcopy(job))
    return added


def maintenance_event_queue(state:dict,now:dt.datetime,horizon:dt.datetime)->List[dict]:
    mr=_maintenance_runtime(state,create=False);out=[]
    for qname,kind in (("repair_queue","repair"),("medical_queue","medical")):
        for job in mr.get(qname,[]) or []:
            if not isinstance(job,dict) or job.get("status")!="active":continue
            tm=parse_iso(job.get("complete_at"))
            if tm is not None and now<=tm<=horizon:out.append({"source":"maintenance_runtime","kind":"maintenance_completion","job_id":job.get("job_id"),"maintenance_kind":kind,"time":tm.strftime("%Y-%m-%dT%H:%M:%S"),"resolver":"maintenance_completion_v1","title":job.get("target_id") or job.get("job_id")})
    return sorted(out,key=lambda e:(e["time"],e.get("job_id") or ""))


def _maintenance_find_active(mr:dict,job_id:str)->Tuple[str,int,dict]:
    for qname in ("repair_queue","medical_queue"):
        q=mr.get(qname) or []
        for i,j in enumerate(q):
            if isinstance(j,dict) and str(j.get("job_id"))==job_id:return qname,i,j
    raise EngineError(f"MAINTENANCE_JOB_NOT_ACTIVE:{job_id}")


def _resolve_maintenance_event(stage:Path,state:dict,tasks:dict,event:dict,when:dt.datetime)->dict:
    mr=_maintenance_runtime(state,create=True);qname,idx,job=_maintenance_find_active(mr,str(event.get("job_id") or ""))
    tm=parse_iso(job.get("complete_at"))
    if tm!=when:raise EngineError(f"MAINTENANCE_EVENT_TIME_MISMATCH:{job.get('job_id')}")
    da=job.get('domain_authorization')
    if da:
        rec=(state.get('standing_authorizations') or {}).get(da['authorization_ref']) or {};grant=rec.get('machine_grant')
        digest=sha256_bytes(json.dumps(grant,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()) if isinstance(grant,dict) else None
        if rec.get('status')!='active' or rec.get('revoked') is True or digest!=da.get('grant_sha256') or parse_iso((grant or {}).get('valid_until')) is None or when>parse_iso(grant['valid_until']):
            blocked=copy.deepcopy(job);blocked['status']='blocked_authorization_changed';blocked['blocked_at']=when.strftime('%Y-%m-%dT%H:%M:%S')
            mr[qname].pop(idx);mr['blocked_jobs'][blocked['job_id']]=blocked
            _append_engine_history(stage/'events.jsonl',{'event_id':f"MAINT-AUTH-BLOCK-{blocked['job_id']}-{when.strftime('%Y%m%d-%H%M%S')}",'game_time':blocked['blocked_at'],'type':'maintenance_completion_blocked','summary':f"GAME ENGINE v{ENGINE_VERSION}暂停到期维修/医疗任务{blocked['job_id']}：持续授权在实际执行时已失效。未执行completion action。",'changes':[{'target':'STATE.engine_runtime.maintenance_runtime.blocked_jobs','action':'authorization_invalid'}],'source':f'GAME ENGINE v{ENGINE_VERSION} {MAINTENANCE_RUNTIME_SCHEMA}','authority_files':['state.json'],'source_job_id':blocked['job_id']})
            return {'source':'maintenance_runtime','job_id':blocked['job_id'],'status':'AI_REQUIRED','semantic_barrier':{'kind':'maintenance_authorization_invalid','job_id':blocked['job_id'],'authorization_ref':da['authorization_ref']}}
    # All completion actions are compare-and-set as one unit. A changed target becomes a semantic barrier,
    # never a partial repair writeback.
    conflicts=[]
    for a in job.get("completion_actions") or []:
        try:cur=get_by_path(state,str(a.get("path"))[6:])
        except Exception:cur=None
        if cur!=a.get("expected_before"):conflicts.append({"path":a.get("path"),"expected":a.get("expected_before"),"current":cur})
        if a.get("op")=="restore_from_path":
            try:src=get_by_path(state,str(a.get("source_path"))[6:])
            except Exception:src=None
            if src!=a.get("source_value_at_enqueue"):conflicts.append({"path":a.get("source_path"),"expected":a.get("source_value_at_enqueue"),"current":src})
    if conflicts:
        blocked=copy.deepcopy(job);blocked["status"]="blocked_authority_changed";blocked["blocked_at"]=when.strftime("%Y-%m-%dT%H:%M:%S");blocked["conflicts"]=conflicts
        mr[qname].pop(idx);mr["blocked_jobs"][blocked["job_id"]]=blocked
        _append_engine_history(stage/"events.jsonl",{"event_id":f"MAINT-BLOCK-{blocked['job_id']}-{when.strftime('%Y%m%d-%H%M%S')}","game_time":when.strftime("%Y-%m-%dT%H:%M:%S"),"type":"maintenance_completion_blocked","summary":f"GAME ENGINE v{ENGINE_VERSION}检测到维修/医疗任务{blocked['job_id']}完成写回目标已改变，已停在语义审计门，未执行任何completion action。","changes":[{"target":"STATE.engine_runtime.maintenance_runtime.blocked_jobs","action":"compare_and_set_conflict"}],"source":f"GAME ENGINE v{ENGINE_VERSION} {MAINTENANCE_RUNTIME_SCHEMA}","authority_files":["state.json"],"zero_time":False})
        return {"source":"maintenance_runtime","job_id":blocked["job_id"],"maintenance_kind":blocked["kind"],"status":"AI_REQUIRED","semantic_barrier":{"kind":"maintenance_authority_conflict","job_id":blocked["job_id"],"time":blocked["blocked_at"],"conflicts":conflicts}}
    changes=[]
    for a in job.get("completion_actions") or []:
        parent,key=_dot_parent(state,str(a["path"])[6:]);parent[key]=copy.deepcopy(a.get("value"));changes.append({"target":a["path"],"action":a["op"]})
    done=copy.deepcopy(job);done["status"]="completed";done["completed_at"]=when.strftime("%Y-%m-%dT%H:%M:%S")
    mr[qname].pop(idx);mr["completed_jobs"][done["job_id"]]=done
    changes.append({"target":f"STATE.engine_runtime.maintenance_runtime.{qname}","action":"complete_and_move_to_completed_jobs"})
    _append_engine_history(stage/"events.jsonl",{"event_id":f"MAINT-DONE-{done['job_id']}-{when.strftime('%Y%m%d-%H%M%S')}","game_time":when.strftime("%Y-%m-%dT%H:%M:%S"),"type":f"{done['kind']}_completion","summary":f"GAME ENGINE v{ENGINE_VERSION}按封板ETA自动完成{done['kind']}任务{done['job_id']}；不生成额外金币费用，医疗任务不自动消耗医疗包。","changes":changes,"source":f"GAME ENGINE v{ENGINE_VERSION} {MAINTENANCE_RUNTIME_SCHEMA}","authority_files":["state.json"],"source_battle_id":done.get("source_battle_id")})
    return {"source":"maintenance_runtime","job_id":done["job_id"],"maintenance_kind":done["kind"],"status":"COMPLETED","actions":changes}


def deterministic_event_queue(state:dict,tasks_doc:dict,now:dt.datetime,horizon:dt.datetime)->List[dict]:
    task_rows=[]
    for row in deterministic_task_queue(tasks_doc,now,horizon,state):
        x=copy.deepcopy(row);x.setdefault("source","task");task_rows.append(x)
    out=task_rows+maintenance_event_queue(state,now,horizon)
    return sorted(out,key=lambda e:(e.get("time") or "",e.get("source") or "",e.get("task_id") or e.get("job_id") or ""))


def _resolve_deterministic_event(stage:Path,state:dict,tasks:dict,event:dict,when:dt.datetime)->dict:
    if event.get("source")=="maintenance_runtime":return _resolve_maintenance_event(stage,state,tasks,event,when)
    task=_task_by_id(tasks,event["task_id"]);fn=RESOLVER_FUNCTIONS[event["resolver"]];return fn(stage,state,tasks,task,when)

def _progress_rule_due_time(task:dict,state:Optional[dict],tasks_doc:dict,now:dt.datetime,horizon:dt.datetime)->Optional[dt.datetime]:
    """Earliest deterministic progress checkpoint in (now, horizon].

    Continuous progress must not depend on an author remembering next_review_at.  We
    schedule the earliest of an explicit review, repeat interval, next milestone/bound,
    or the requested time-advance horizon so the numeric state is always current.
    """
    if state is None or horizon<=now:return None
    rp=task.get("runtime_policy") or {};mon=rp.get("monitor") or {};rule=rp.get("progress_rule") or (task.get("task_data") or {}).get("progress_rule")
    if _validate_progress_rule(rule):return None
    try:
        root,path=_automation_root(state,tasks_doc,rule["target"]);parent,key=_dot_parent(root,path);cur=parent.get(key)
    except Exception:
        return None
    if not isinstance(cur,(int,float)) or isinstance(cur,bool) or not math.isfinite(float(cur)):return None
    rate=float(rule["rate_per_second"]);cur=float(cur);candidates=[]
    origin=parse_iso(mon.get("last_reviewed_at")) or now
    nr=parse_iso(mon.get("next_review_at")) if mon.get("next_review_at") else None
    if nr is not None and now<nr<=horizon:candidates.append(nr)
    repeat=rule.get("repeat_seconds")
    if isinstance(repeat,int) and not isinstance(repeat,bool) and repeat>0:
        last=origin
        nxt=last+dt.timedelta(seconds=repeat)
        if nxt<=now:
            steps=int((now-last).total_seconds()//repeat)+1;nxt=last+dt.timedelta(seconds=steps*repeat)
        if now<nxt<=horizon:candidates.append(nxt)
    thresholds=[]
    for m in rule.get("milestones") or []:
        if isinstance(m,dict) and isinstance(m.get("threshold"),(int,float)) and not isinstance(m.get("threshold"),bool):thresholds.append(float(m["threshold"]))
    bound=float(rule["maximum"] if rate>0 else rule["minimum"]);thresholds.append(bound)
    for th in thresholds:
        dist=(th-cur)/rate
        if dist>0:
            # Authority timestamps are second-granular.  Round crossing times upward;
            # flooring a fractional crossing can reschedule the same pre-threshold second
            # forever (for example 0 -> 1 at 0.3 units/s crosses at 3.333s).
            whole_seconds=max(1,int(math.ceil(dist-1e-12)))
            when=origin+dt.timedelta(seconds=whole_seconds)
            if when<=now:candidates.append(now)
            elif when<=horizon:candidates.append(when)
    # Always materialize current progress at the requested horizon when movement remains.
    if (rate>0 and cur<float(rule["maximum"])) or (rate<0 and cur>float(rule["minimum"])):
        candidates.append(horizon)
    return min(candidates) if candidates else None


def _deterministic_event_precedes_barrier(event:dict,event_time:dt.datetime,hard:dt.datetime,barrier:Optional[dict])->bool:
    """Continuous mechanical progress accrues through the exact semantic-boundary instant."""
    if barrier is None:return event_time<=hard
    if event_time<hard:return True
    return event_time==hard and str(event.get("resolver") or "")=="progress_rule_v1"


def deterministic_task_queue(tasks_doc: dict, now: dt.datetime, horizon: dt.datetime, state: Optional[dict]=None) -> List[dict]:
    out=[]
    for t in tasks_doc.get("active_tasks",[]) or []:
        mon=_task_monitor(tasks_doc,t);resolver=str(mon.get("resolver") or "")
        if mon.get("requires_ai_review") is not False or not callable(RESOLVER_FUNCTIONS.get(resolver)):continue
        if _task_execution_coverage(state,tasks_doc,t,now,horizon):continue
        if resolver=="progress_rule_v1":
            due=_progress_rule_due_time(t,state,tasks_doc,now,horizon)
            if due is not None:out.append({"task_id":t.get("task_id"),"time":due.strftime("%Y-%m-%dT%H:%M:%S"),"resolver":resolver,"title":t.get("title")})
            continue
        nr=parse_iso(mon.get("next_review_at")) if mon.get("next_review_at") else None
        if nr is not None and now <= nr <= horizon:out.append({"task_id":t.get("task_id"),"time":nr.strftime("%Y-%m-%dT%H:%M:%S"),"resolver":resolver,"title":t.get("title")})
    return sorted(out,key=lambda e:(e["time"],e.get("task_id") or ""))


def _next_ai_monitor_time(tasks_doc: dict, now: dt.datetime, horizon: dt.datetime, state: Optional[dict]=None) -> Optional[dict]:
    vals=[]
    for t in tasks_doc.get("active_tasks",[]) or []:
        mon=_task_monitor(tasks_doc,t)
        coverage=_task_execution_coverage(state,tasks_doc,t,now,horizon)
        if coverage:vals.append(coverage)
        if _task_player_decision_gate_open(t):
            vals.append({"time":now,"task_id":t.get("task_id"),"title":t.get("title"),"kind":"task_player_decision_gate","decision_gate":_compact_value(t.get("decision_gate"),320),"resolution_required":"Commander decision is explicitly required before time advance may continue; Engine must not infer or auto-resolve the choice."})
        if not mon.get("requires_ai_review",True):
            due=parse_iso(mon.get('next_review_at')) if mon.get('next_review_at') else None
            if due and due<now and mon.get('resolver') in RESOLVER_FUNCTIONS and mon.get('resolver')!='progress_rule_v1':
                vals.append({'time':now,'task_id':t.get('task_id'),'title':t.get('title'),'kind':'task_overdue_reconciliation','scheduled_time':due.isoformat(),'resolution_required':'Reconcile HISTORY and last reviewed time before explicitly catching up or rescheduling; never silently skip or invent historical income.'})
            continue
        watch=_watch_condition_status(state,t)
        if watch.get("configured"):
            if watch.get("triggered"):
                vals.append({"time":now,"task_id":t.get("task_id"),"title":t.get("title"),"kind":"task_watch_condition","watch_condition":copy.deepcopy(watch),"resolution_required":"AI must review the changed canonical STATE. Before continuing, an authoritative task patch must rebase watch_condition.baseline_digest to current_digest (or explicitly replace/retire the watcher); Engine never auto-acknowledges a changed watcher."})
            continue
        nr=parse_iso(mon.get("next_review_at")) if mon.get("next_review_at") else None
        if nr is not None:
            if now < nr <= horizon:vals.append({"time":nr,"task_id":t.get("task_id"),"title":t.get("title"),"kind":"task_ai_review"})
            elif nr <= now:vals.append({"time":now,"task_id":t.get("task_id"),"title":t.get("title"),"kind":"task_ai_review_now"})
            continue
        if mon.get("review_on_time_advance") and mon.get("mode") in {"on_advance","continuous","external_wait"}:
            vals.append({"time":now,"task_id":t.get("task_id"),"title":t.get("title"),"kind":"task_ai_review_now"})
    return min(vals,key=lambda x:(x["time"],x.get("task_id") or "")) if vals else None


# === VOYAGER_DEV_MODULE: business_settlement ===
BUSINESS_RULE_SCHEMA='BUSINESS_DAILY_RULE_V1'
BUSINESS_RUNTIME_SCHEMA='BUSINESS_RUNTIME_V1'


def _business_rule(task):
    rule=(task.get('runtime_policy') or {}).get('business_rule')
    if not isinstance(rule,dict) or rule.get('schema')!=BUSINESS_RULE_SCHEMA:raise EngineError('BUSINESS_RULE_REQUIRED')
    if not re.fullmatch(r'[A-Za-z0-9_-]{1,80}',str(rule.get('business_id') or '')):raise EngineError('BUSINESS_ID_INVALID')
    if rule.get('currency')!='copper' or rule.get('repeat_seconds')!=86400:raise EngineError('BUSINESS_PERIOD_OR_CURRENCY_UNSUPPORTED')
    if not isinstance(rule.get('fixed_costs'),dict) or any(type(v) is not int or v<0 for v in rule['fixed_costs'].values()):raise EngineError('BUSINESS_FIXED_COST_INVALID')
    if not rule.get('authorization_basis') or not rule.get('effective_from'):raise EngineError('BUSINESS_AUTHORIZATION_AND_EPOCH_REQUIRED')
    return rule


def _business_runtime(state,bid):
    rt=state.get('engine_runtime',{}).get('business_runtime_v1')
    if not isinstance(rt,dict) or rt.get('schema')!=BUSINESS_RUNTIME_SCHEMA:raise EngineError('BUSINESS_MIGRATION_REQUIRED')
    row=rt.get('businesses',{}).get(bid)
    if not isinstance(row,dict):raise EngineError('BUSINESS_NOT_REGISTERED')
    return row


def _business_day_key(iso):
    when=parse_iso(iso)
    if when is None or when.isoformat()!=iso:raise EngineError('BUSINESS_CANONICAL_TIME_REQUIRED')
    return iso


def _business_integer(value,name):
    if type(value) is not int or value<0:raise EngineError('BUSINESS_NONNEGATIVE_INTEGER:'+name)
    return value


def _business_v1_validate_day(record):
    required={'scheduled_at','record_kind','source_refs','cash_receipts_copper','cash_purchases_copper','other_cash_expenses_copper','gross_sales_copper','cogs_copper','inventory'}
    if not isinstance(record,dict) or set(record)!=required:raise EngineError('BUSINESS_DAY_SCHEMA')
    _business_day_key(record['scheduled_at'])
    if record['record_kind'] not in ('actual','commander_accepted_simulation'):raise EngineError('BUSINESS_FORECAST_IS_NOT_ACTUAL')
    if not isinstance(record['source_refs'],list) or not 1<=len(record['source_refs'])<=40 or any(not isinstance(x,str) or not x.strip() or len(x)>500 for x in record['source_refs']):raise EngineError('BUSINESS_SOURCE_REQUIRED')
    for field in required-{'scheduled_at','record_kind','source_refs','inventory'}:_business_integer(record[field],field)
    inv=record['inventory']
    if not isinstance(inv,dict) or set(inv)!={'status','opening_basis','opening','purchases','sold','waste','closing'} or inv['status']!='confirmed' or inv['opening_basis'] not in ('stocktake','previous_close'):raise EngineError('BUSINESS_INVENTORY_UNCONFIRMED')
    for field in ('opening','purchases','sold','waste','closing'):
        if not isinstance(inv[field],dict) or len(inv[field])>2000:raise EngineError('BUSINESS_INVENTORY_SCHEMA')
        for sku,n in inv[field].items():
            if not re.fullmatch(r'[A-Za-z0-9_-]{1,100}',str(sku)) or type(n) is not int or n<0:raise EngineError('BUSINESS_SKU_QUANTITY_INVALID')
    keys=set().union(*(set(inv[k]) for k in ('opening','purchases','sold','waste','closing')))
    for sku in keys:
        expected=inv['opening'].get(sku,0)+inv['purchases'].get(sku,0)-inv['sold'].get(sku,0)-inv['waste'].get(sku,0)
        if expected<0 or inv['closing'].get(sku,0)!=expected:raise EngineError('BUSINESS_INVENTORY_EQUATION:'+sku)
    return record


def _business_prepaid_expense(state,rule,iso):
    total=0;covered=[]
    for path in rule.get('prepaid_contract_refs',[]):
        contract=get_by_path(state,path);day=iso[:10]
        lo=contract.get('from');hi=contract.get('through')
        if not isinstance(lo,str) or not isinstance(hi,str) or parse_iso(lo+'T00:00:00') is None or parse_iso(hi+'T00:00:00') is None:raise EngineError('BUSINESS_PREPAID_CONTRACT_INVALID')
        if lo<=day<=hi:
            daily=sum(_business_integer(contract.get(k),k) for k in ('daily_salary_copper','daily_meals_copper'))
            days=(parse_iso(hi+'T00:00:00')-parse_iso(lo+'T00:00:00')).days+1
            if contract.get('days')!=days or contract.get('total_paid_copper')!=daily*days or sum(contract.get(k,0) for k in ('salary_prepaid_copper','meals_prepaid_copper'))!=daily*days:raise EngineError('BUSINESS_PREPAID_PAYMENT_UNVERIFIED')
            total+=daily;covered.append({'contract_ref':'state:'+path,'expense_copper':daily,'additional_cash_payment_copper':0})
    return total,covered


def _business_v1_assessment(state,task,iso):
    try:
        rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);_account_units(state,rule['account_id'],'copper')
        if iso<rule['effective_from']:raise EngineError('BUSINESS_NO_HISTORICAL_REPLAY')
        saved=row['inputs'].get(iso)
        if not saved:return {'status':'NEEDS_EVIDENCE','missing':['confirmed_day_record','current_SKU_stocktake'],'scheduled_at':iso}
        record=_business_validate_day(saved['record'])
        if saved.get('record_sha256')!=_repair_digest(record) or saved.get('rule_sha256')!=_repair_digest(rule) or not saved.get('authorization_evidence') or not saved.get('command_id'):raise EngineError('BUSINESS_INPUT_BINDING_INVALID')
        if record['scheduled_at']!=iso:raise EngineError('BUSINESS_INPUT_PERIOD_MISMATCH')
        inv=record['inventory']
        if row.get('inventory_status')=='confirmed':
            if row.get('inventory')!=inv['opening']:raise EngineError('BUSINESS_OPENING_STOCK_MISMATCH')
        elif inv['opening_basis']!='stocktake':raise EngineError('BUSINESS_FIRST_STOCKTAKE_REQUIRED')
        expense=sum(rule['fixed_costs'].values());prepaid,contracts=_business_prepaid_expense(state,rule,iso)
        debit=record['cash_purchases_copper']+record['other_cash_expenses_copper']+expense
        delta=record['cash_receipts_copper']-debit
        available=_account_units(state,rule['account_id'],'copper')-_account_reserved(state,rule['account_id'],'copper')
        if available+delta<0:return {'status':'INSUFFICIENT_FUNDS','missing':['cash_shortfall'],'shortfall_copper':-(available+delta),'scheduled_at':iso}
        return {'status':'READY','scheduled_at':iso,'cash_delta_copper':delta,'cash_debits_copper':debit,'fixed_costs_copper':expense,'prepaid_expense_copper':prepaid,'prepaid_contracts':contracts,'profit_copper':record['gross_sales_copper']-record['cogs_copper']-record['other_cash_expenses_copper']-expense-prepaid,'record_sha256':saved['record_sha256'],'rule_sha256':saved['rule_sha256']}
    except Exception as ex:return {'status':'INVALID','missing':[str(ex)],'scheduled_at':iso}


def _business_day_record(state,tasks,payload):
    task=_task_by_id(tasks,payload['task_id']);rule=_business_rule(task);row=_business_runtime(state,rule['business_id'])
    if payload['account_id']!=rule['account_id']:raise EngineError('BUSINESS_ACCOUNT_TARGET_MISMATCH')
    # Only a real gateway/embedding host may confirm previously unknown actuals.
    env=_host_intent_scope.get()
    if payload.get('authorization')!='host_intent' or not isinstance(env,dict) or env.get('command')!=payload or env.get('decision')!='approved' or not env.get('evidence_ref'):raise EngineError('BUSINESS_ACTUALS_REQUIRE_TRUSTED_HOST_CONFIRMATION')
    record=copy.deepcopy(_business_validate_day(payload['day_record']));iso=record['scheduled_at'];now=state['game_time'];mon=_task_monitor(tasks,task)
    if iso<rule['effective_from'] or iso!=mon.get('next_review_at'):raise EngineError('BUSINESS_RECORD_NOT_CURRENT_DUE_PERIOD')
    if parse_iso(iso)>parse_iso(now):raise EngineError('BUSINESS_FUTURE_ACTUALS_FORBIDDEN')
    if iso in row['settlements']:raise EngineError('BUSINESS_PERIOD_ALREADY_SETTLED')
    digest=_repair_digest(record);old=row['inputs'].get(iso)
    if old and old['record_sha256']!=digest:raise EngineError('BUSINESS_INPUT_ALREADY_CONFIRMED_USE_EXPLICIT_CORRECTION')
    if old:return {'kind':'business_day_record','task_id':task['task_id'],'assessment':_business_assessment(state,task,iso),'record_sha256':old['record_sha256'],'rule_sha256':old['rule_sha256'],'already_confirmed':True,'cash_changed':False,'changes':[]}
    proof={'kind':'host_confirmed_record','evidence_ref':env['evidence_ref'],'intent_sha256':_repair_digest(env),'record_kind':record['record_kind']}
    row['inputs'][iso]={'record':record,'record_sha256':digest,'rule_sha256':_repair_digest(rule),'authorization_evidence':proof,'command_id':payload['command_id'],'recorded_at':now}
    assessment=_business_assessment(state,task,iso)
    if assessment['status']=='INVALID':raise EngineError('BUSINESS_INPUT_INVALID:'+str(assessment['missing']))
    required_debit=record['cash_purchases_copper']+record['other_cash_expenses_copper']+sum(rule['fixed_costs'].values())
    if _business_integer(payload.get('cash_debit_limit_copper'),'cash_debit_limit_copper')<required_debit:raise EngineError('BUSINESS_CASH_DEBIT_LIMIT_INSUFFICIENT')
    return {'kind':'business_day_record','task_id':task['task_id'],'assessment':assessment,'record_sha256':digest,'rule_sha256':_repair_digest(rule),'cash_changed':False,'changes':[{'target':'state:engine_runtime.business_runtime_v1.businesses.'+rule['business_id']+'.inputs','action':'record_host_confirmed_business_evidence'}]}


def _business_v1_resolver_daily(stage,state,tasks,task,when):
    iso=when.isoformat();rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);prior=row['settlements'].get(iso)
    if prior:
        if prior['rule_sha256']!=_repair_digest(rule) or row['inputs'].get(iso,{}).get('record_sha256')!=prior['record_sha256']:raise EngineError('BUSINESS_SETTLED_INPUT_CONFLICT')
        return {**copy.deepcopy(prior),'status':'ALREADY_APPLIED'}
    if state['game_time']!=iso or _task_monitor(tasks,task).get('next_review_at')!=iso:raise EngineError('BUSINESS_SETTLEMENT_TIME_MISMATCH')
    check=_business_assessment(state,task,iso)
    if check['status']!='READY':return {'status':'AI_REQUIRED','task_id':task['task_id'],'semantic_barrier':{'kind':'business_reconciliation','task_id':task['task_id'],'assessment':check}}
    record=row['inputs'][iso]['record'];aid=rule['account_id'];before=_account_units(state,aid,'copper');key=rule['business_id']+'|'+iso+'|daily_close';eid='BUSINESS-'+sha256_bytes(key.encode())[:24]
    token=_account_command_scope.set(eid)
    try:cash=_account_post(state,aid,'copper',check['cash_delta_copper'])
    finally:_account_command_scope.reset(token)
    nxt=_roll_daily(when)
    receipt={**check,'status':'COMPLETE','business_key':key,'event_id':eid,'task_id':task['task_id'],'business_id':rule['business_id'],'account_id':aid,'period_start':(when-dt.timedelta(days=1)).isoformat(),'scheduled_at':iso,'next_at':nxt,'input_command_id':row['inputs'][iso]['command_id'],'source_refs':record['source_refs'],'record_kind':record['record_kind'],'inventory_status':record['inventory']['status'],'cash_before_copper':before,'cash_after_copper':_account_units(state,aid,'copper'),'cash_entry_id':cash['entry_id'],'cash_receipts_copper':record['cash_receipts_copper'],'cash_purchases_copper':record['cash_purchases_copper'],'other_cash_expenses_copper':record['other_cash_expenses_copper'],'gross_sales_copper':record['gross_sales_copper'],'cogs_copper':record['cogs_copper'],'fixed_cost_items':copy.deepcopy(rule['fixed_costs'])}
    if record['inventory']['status']=='continuous_simulated':
        receipt.update(authorization_evidence=copy.deepcopy(row['inputs'][iso]['authorization_evidence']),accounting_journal=_business_journal(record,check,row['autonomy_policy']),inventory_movements=copy.deepcopy(record['inventory']),physical_receipts_confirmed=False)
    if record['record_kind']=='actual' and record['inventory']['opening_basis']=='stocktake' and row.get('autonomy_policy'):
        receipt['stocktake_reconciliation']=business_stocktake_comparison(state,task,record)
    row['settlements'][iso]=receipt;row['inventory']=copy.deepcopy(record['inventory']['closing']);row['inventory_status']=record['inventory']['status'];row['last_settled_at']=iso
    td=task['task_data'];td.update(last_payroll_at=iso,next_payroll_at=nxt,next_close_at=nxt,last_full_shop_day=iso[:10],as_of=iso,latest_shop_balance_copper=receipt['cash_after_copper'],latest_cash_copper=receipt['cash_after_copper'],cash_silver=receipt['cash_after_copper']/100)
    mon=task['runtime_policy']['monitor'];mon.update(last_reviewed_at=iso,next_review_at=nxt)
    cover=get_by_path(state,'world_state_overrides.freeport_xilu9_current.hawke_commercial_cover') if rule['business_id']=='YUHUO' else None
    mirror_changes=[]
    if cover is not None:
        for key in ('next_payroll_at','next_full_shop_close_at'):
            cover['simulation_current'][key]=nxt
            mirror_changes.append({'target':'state:world_state_overrides.freeport_xilu9_current.hawke_commercial_cover.simulation_current.'+key,'action':'derive_verified_business_next_node'})
        cover['shop_cash_continuation_83631205']['next_close_at']=nxt
        mirror_changes.append({'target':'state:world_state_overrides.freeport_xilu9_current.hawke_commercial_cover.shop_cash_continuation_83631205.next_close_at','action':'derive_verified_business_next_node'})
    changes=[{'target':'state:engine_runtime.business_runtime_v1.businesses.'+rule['business_id'],'action':'settle_verified_day_and_roll_inventory'},{'target':'state:engine_runtime.account_registry_v1','action':'post_independent_cash_once'},{'target':'tasks:active_tasks','action':'roll_business_daily_monitor'}]+[{'target':'state:'+v['path'],'action':'derive_account_view'} for v in _account_record(state,aid).get('legacy_read_only_views',[])]
    _append_engine_history(stage/'events.jsonl',{'event_id':eid,'game_time':iso,'type':'business_daily_settlement','summary':'独立店铺依据可审计经营输入完成日结，保留真实或模拟证据类别；成本与现金分列，预付合同不重复付款。','source':'GAME ENGINE business_daily_settlement_v1','source_task_id':task['task_id'],'authority_files':['state.json','tasks.json'],'changes':changes+mirror_changes,'business_settlement':receipt,'finance_independent':{'account_id':aid,'currency':'copper','delta_units':check['cash_delta_copper'],'cash_entry_id':cash['entry_id']}})
    # Session execution diagnostics are added to its returned row, never to authority.
    return copy.deepcopy(receipt)


def _task_execution_coverage(state,tasks,task,now,horizon):
    mon=_task_monitor(tasks,task);mode=mon.get('mode');resolver=str(mon.get('resolver') or '');nr=parse_iso(mon.get('next_review_at')) if mon.get('next_review_at') else None
    if mode!='scheduled':return None
    due=max(now,nr) if nr else now
    if due>horizon:return None
    if mon.get('requires_ai_review') is True:return None
    problem=None;assessment=None
    if nr is None:problem='SCHEDULED_DEADLINE_MISSING'
    elif not callable(RESOLVER_FUNCTIONS.get(resolver)):problem='SCHEDULED_RESOLVER_UNAVAILABLE'
    elif resolver=='business_daily_settlement_v1':
        assessment=_business_assessment(state,task,nr.isoformat()) if isinstance(state,dict) else {'status':'NEEDS_STATE'}
        if assessment['status']!='READY':problem='BUSINESS_'+assessment['status']
    if not problem:return None
    return {'time':due,'scheduled_time':nr.isoformat() if nr else None,'task_id':task.get('task_id'),'title':task.get('title'),'kind':'business_reconciliation' if resolver=='business_daily_settlement_v1' else 'task_execution_uncovered','reason':problem,'assessment':assessment,'resolution_required':'Use the trusted typed business_day_record input for confirmed current records, or repair the declared resolver. Unknown income/inventory is never zero; no historical replay.'}


def _scheduler_coverage(state,tasks,save_set_id=None):
    now=parse_iso(state['game_time']);end=now+dt.timedelta(days=1)
    rows=[]
    for task in tasks.get('active_tasks',[]):
        mon=_task_monitor(tasks,task);issue=_task_execution_coverage(state,tasks,task,now,end)
        rows.append({'task_id':task['task_id'],'mode':mon.get('mode'),'resolver':mon.get('resolver'),'callable_resolver':callable(RESOLVER_FUNCTIONS.get(str(mon.get('resolver') or ''))),'next_at':mon.get('next_review_at'),'execution_status':'ACTION_REQUIRED' if issue else ('AI_MANAGED' if mon.get('requires_ai_review') else 'EXECUTABLE' if callable(RESOLVER_FUNCTIONS.get(str(mon.get('resolver') or ''))) else 'EVENT_WATCHER'),'issue':{**issue,'time':issue['time'].isoformat()} if issue else None})
    issues=[r['issue'] for r in rows if r['issue']]
    return {'packet':'SCHEDULER_COVERAGE_V1','status':'ACTION_REQUIRED' if issues else 'COVERED','game_time':state['game_time'],'save_set_id':save_set_id,'can_advance_through_24h':not issues,'next_blocker':min(issues,key=lambda x:(x['time'],x['task_id'])) if issues else None,'tasks':rows}


def scheduler_coverage_packet(base=ROOT):
    with SnapshotContext(base):
        ensure_source_ready(base)
        return _scheduler_coverage(read_json_view(Path(base)/'state.json'),read_json_view(Path(base)/'tasks.json'),read_json_view(Path(base)/'manifest.json')['save_set_id'])


def business_query_packet(base=ROOT,task_id='TSK-YUHUO-OPERATIONS'):
    with SnapshotContext(base):
        ensure_source_ready(base);state=read_json_view(Path(base)/'state.json');tasks=read_json_view(Path(base)/'tasks.json');task=_task_by_id(tasks,task_id);rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);iso=_task_monitor(tasks,task).get('next_review_at')
        return {'packet':'BUSINESS_QUERY_V1','save_set_id':read_json_view(Path(base)/'manifest.json')['save_set_id'],'game_time':state['game_time'],'task_id':task_id,'business_id':rule['business_id'],'cash_copper':_account_units(state,rule['account_id'],'copper'),'next_at':iso,'assessment':_business_assessment(state,task,iso),'last_settled_at':row.get('last_settled_at'),'latest_receipt':row['settlements'].get(row.get('last_settled_at')),'inventory_status':row['inventory_status'],'fixed_costs':rule['fixed_costs'],'prepaid_at_next_close':_business_prepaid_expense(state,rule,iso),'historical_gaps':row.get('historical_gaps',[]),'balance_evidence':_business_balance_evidence(state,rule['account_id']),'input_entry':'standing authorized simulation is registered automatically only when due; actual business_day_record still requires the existing trusted host gateway'}


def _business_v1_integrity_report(state,tasks,base=None):
    rt=state.get('engine_runtime',{}).get('business_runtime_v1')
    if rt is None:
        errors=['BUSINESS_MIGRATION_REQUIRED'] if any(_task_monitor(tasks,t).get('resolver')=='business_daily_settlement_v1' for t in tasks.get('active_tasks',[])) else []
        return {'status':'FAIL' if errors else 'LEGACY','errors':errors}
    errors=[]
    try:
        if rt.get('schema')!=BUSINESS_RUNTIME_SCHEMA:raise EngineError('BUSINESS_RUNTIME_SCHEMA')
        for bid,row in rt['businesses'].items():
            task=_task_by_id(tasks,row['task_id']);rule=_business_rule(task)
            if rule['business_id']!=bid or row['inventory_status'] not in ('unknown','confirmed'):raise EngineError('BUSINESS_ID_OR_STOCK_STATUS')
            for iso,saved in row['inputs'].items():
                record=_business_validate_day(saved['record'])
                if iso!=record['scheduled_at'] or iso<rule['effective_from'] or saved['record_sha256']!=_repair_digest(record) or not saved.get('authorization_evidence'):raise EngineError('BUSINESS_INPUT_CONTRACT')
                if base is not None:
                    ev=history_lookup(base,command_id=saved['command_id'])
                    if not ev or ev.get('domain_kind')!='business_day_record' or ev.get('authorization',{}).get('evidence_ref')!=saved['authorization_evidence'].get('evidence_ref') or ev.get('domain_effect',{}).get('record_sha256')!=saved['record_sha256'] or ev.get('domain_effect',{}).get('rule_sha256')!=saved['rule_sha256']:raise EngineError('BUSINESS_INPUT_HISTORY_MISSING')
            for iso,rec in row['settlements'].items():
                saved=row['inputs'].get(iso)
                if not saved or rec['record_sha256']!=saved['record_sha256'] or rec['cash_after_copper']-rec['cash_before_copper']!=rec['cash_delta_copper']:raise EngineError('BUSINESS_SETTLEMENT_BINDING')
                matches=[x for x in _account_registry(state)['ledger'] if x['entry_id']==rec['cash_entry_id']]
                if len(matches)!=1 or matches[0]['delta_units']!=rec['cash_delta_copper']:raise EngineError('BUSINESS_CASH_RECEIPT_MISSING')
                if base is not None:
                    ev=history_lookup(base,event_id=rec['event_id'])
                    if not ev or ev.get('business_settlement')!=rec:raise EngineError('BUSINESS_EVENT_RECEIPT_MISSING')
    except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors}


def _business_v1_settlement_proofs(base,parent,old_state,new_state,new_events):
    """Recompute each new close against its confirmed parent input; exact coverage only."""
    old_rows=old_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    new_rows=new_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    tasks=read_json(Path(parent)/'tasks.json');proofs={};covered=set()
    for bid,row in new_rows.items():
        previous=old_rows.get(bid,{});old_closes=previous.get('settlements',{})
        for iso,receipt in old_closes.items():
            if row['settlements'].get(iso)!=receipt:raise EngineError('BUSINESS_OLD_RECEIPT_IMMUTABLE')
        fresh=[(iso,r) for iso,r in row['settlements'].items() if iso not in old_closes]
        if not fresh:continue
        task=_task_by_id(tasks,row['task_id']);rule=_business_rule(task)
        working=copy.deepcopy(old_state)
        for iso,rec in sorted(fresh):
            matches=[ev for ev in new_events if ev.get('event_id')==rec.get('event_id') and ev.get('type')=='business_daily_settlement']
            if len(matches)!=1 or matches[0].get('business_settlement')!=rec:raise EngineError('BUSINESS_EVENT_RECEIPT_MISMATCH')
            check=_business_assessment(working,task,iso)
            if check['status']!='READY' or rec.get('status')!='COMPLETE':raise EngineError('BUSINESS_RECEIPT_NO_VALID_PARENT_INPUT')
            for key,value in check.items():
                if key!='status' and rec.get(key)!=value:raise EngineError('BUSINESS_RECEIPT_RECOMPUTE_MISMATCH:'+key)
            if rec.get('business_id')!=bid or rec.get('task_id')!=task['task_id'] or rec.get('account_id')!=rule['account_id']:raise EngineError('BUSINESS_RECEIPT_SUBJECT_MISMATCH')
            before=_account_units(working,rule['account_id'],'copper')
            if rec.get('cash_before_copper')!=before or rec.get('cash_after_copper')!=before+check['cash_delta_copper']:raise EngineError('BUSINESS_RECEIPT_CASH_MISMATCH')
            record=_business_runtime(working,bid)['inputs'][iso]['record']
            if row['inputs'].get(iso)!=_business_runtime(working,bid)['inputs'][iso]:raise EngineError('BUSINESS_CONFIRMED_INPUT_IMMUTABLE')
            if rec.get('fixed_cost_items')!=rule['fixed_costs'] or any(rec.get(k)!=record[k] for k in ('cash_receipts_copper','cash_purchases_copper','other_cash_expenses_copper','gross_sales_copper','cogs_copper','record_kind','source_refs')):raise EngineError('BUSINESS_RECEIPT_INPUT_AMOUNTS')
            cash=[x for x in _account_registry(new_state)['ledger'] if x['entry_id']==rec.get('cash_entry_id')]
            if len(cash)!=1 or cash[0]['command_id']!=rec['event_id'] or cash[0]['account_id']!=rule['account_id'] or cash[0]['currency']!='copper' or cash[0]['delta_units']!=check['cash_delta_copper']:raise EngineError('BUSINESS_CASH_SOURCE_MISMATCH')
            proofs[cash[0]['entry_id']]=cash[0]
            prefix='state:engine_runtime.business_runtime_v1.businesses.'+bid+'.settlements.'+iso
            # Accept exactly the recomputed fixed-cost outputs, not arbitrary new prices.
            covered.add(prefix+'.fixed_costs_copper')
            covered.update(prefix+'.fixed_cost_items.'+k for k in rule['fixed_costs'])
            _account_post(working,rule['account_id'],'copper',check['cash_delta_copper'])
            current=_business_runtime(working,bid);current['inventory']=copy.deepcopy(record['inventory']['closing']);current['inventory_status']='confirmed'
    return proofs,covered


RESOLVER_FUNCTIONS['business_daily_settlement_v1']=_business_v1_resolver_daily
DETERMINISTIC_RESOLVERS.add('business_daily_settlement_v1')
TASK_AI_BARRIER_KINDS.update({'business_reconciliation','task_execution_uncovered'})
# === VOYAGER_DEV_MODULE: autonomous_business ===
# V14.64: simulation is a distinct evidence class. No host-intent context is synthesized.
_BUSINESS_V1_VALIDATE = _business_v1_validate_day
_BUSINESS_V1_ASSESS = _business_v1_assessment
_BUSINESS_V1_RESOLVE = _business_v1_resolver_daily
_BUSINESS_V1_INTEGRITY = _business_v1_integrity_report
_BUSINESS_V1_PROOFS = _business_v1_settlement_proofs
AUTONOMOUS_BUSINESS_SCHEMA = 'AUTONOMOUS_BUSINESS_POLICY_V1'


def _business_validate_day(record):
    if not isinstance(record, dict) or record.get('inventory', {}).get('status') != 'continuous_simulated':
        if isinstance(record, dict) and record.get('record_kind') == 'commander_accepted_simulation':
            raise EngineError('BUSINESS_SIMULATION_CANNOT_CLAIM_PHYSICAL_STOCKTAKE')
        return _BUSINESS_V1_VALIDATE(record)
    if record.get('record_kind') != 'commander_accepted_simulation':
        raise EngineError('BUSINESS_SIMULATED_INVENTORY_EVIDENCE_CLASS')
    inv = record['inventory']
    if inv.get('opening_basis') not in ('authorized_simulation_anchor', 'previous_simulated_close', 'previous_confirmed_close'):
        raise EngineError('BUSINESS_SIMULATION_OPENING_BASIS')
    shadow = copy.deepcopy(record)
    shadow['inventory']['status'] = 'confirmed'
    shadow['inventory']['opening_basis'] = 'previous_close'
    _BUSINESS_V1_VALIDATE(shadow)
    return record


def _business_policy(state, task, iso, enforce_operating=True):
    rule = _business_rule(task); row = _business_runtime(state, rule['business_id'])
    policy = row.get('autonomy_policy')
    if not isinstance(policy, dict) or policy.get('schema') != AUTONOMOUS_BUSINESS_SCHEMA:
        raise EngineError('BUSINESS_AUTONOMY_NOT_GRANTED')
    if row.get('autonomy_policy_sha256') != _repair_digest(policy):
        raise EngineError('BUSINESS_AUTONOMY_POLICY_DIGEST')
    if policy.get('status') not in ('active','paused','revoked'):raise EngineError('BUSINESS_POLICY_STATUS')
    if enforce_operating and (policy.get('status') != 'active' or not policy['effective_from'] <= iso or (policy.get('expires_at') and iso > policy['expires_at'])):
        raise EngineError('BUSINESS_AUTONOMY_INACTIVE')
    if (policy['business_id'], policy['task_id'], policy['account_id']) != (rule['business_id'], task['task_id'], rule['account_id']):
        raise EngineError('BUSINESS_AUTONOMY_SUBJECT')
    if policy['rule_sha256'] != _repair_digest(rule):raise EngineError('BUSINESS_AUTONOMY_RULE_CHANGED')
    if policy.get('evidence_class') != 'commander_accepted_simulation' or policy.get('authority') != 'explicit_commander_upgrade_instruction':
        raise EngineError('BUSINESS_AUTONOMY_AUTHORITY')
    if not policy.get('source_ref') or not policy.get('grant_event_id') or policy.get('allow_cross_account_transfer') is not False:
        raise EngineError('BUSINESS_AUTONOMY_SCOPE')
    if enforce_operating and row.get('risk_flags'):raise EngineError('BUSINESS_MAJOR_RISK_REQUIRES_COMMANDER:'+','.join(row['risk_flags']))
    for k in ('daily_revenue_limit_copper','daily_purchase_limit_copper','daily_cash_debit_limit_copper','minimum_cash_reserve_copper','daily_units_limit'):
        _business_integer(policy[k], k)
    model = policy['model']
    if not isinstance(model, dict) or not model or len(model) > 2000:raise EngineError('BUSINESS_AUTONOMY_MODEL')
    for sku, m in model.items():
        if not re.fullmatch('[A-Za-z0-9_-]{1,100}', sku):raise EngineError('BUSINESS_AUTONOMY_SKU')
        for k in ('unit_cost_copper','unit_price_copper','base_daily_demand','reorder_threshold','target_stock','purchase_batch'):
            _business_integer(m[k],sku+'.'+k)
        if m['unit_price_copper'] < m['unit_cost_copper'] or m['target_stock'] < m['reorder_threshold']:
            raise EngineError('BUSINESS_AUTONOMY_MODEL_BOUNDS')
    return policy


def _business_autonomous_input(state, task, iso):
    """Pure generation: planning never posts income or purchases, including future previews."""
    rule = _business_rule(task); row = _business_runtime(state,rule['business_id']); p = _business_policy(state,task,iso)
    if iso < rule['effective_from']:raise EngineError('BUSINESS_NO_HISTORICAL_REPLAY')
    last = row.get('last_settled_at')
    expected = _roll_daily(parse_iso(last)) if last else p['effective_from']
    if iso != expected:raise EngineError('BUSINESS_SIMULATION_PERIOD_NOT_CONTIGUOUS')
    opening = copy.deepcopy(row['inventory'] if last else p['opening_simulated_inventory'])
    if set(opening) != set(p['model']):raise EngineError('BUSINESS_SIMULATION_SKU_COVERAGE')
    inv = {'status':'continuous_simulated','opening_basis':('previous_confirmed_close' if row.get('inventory_status')=='confirmed' else 'previous_simulated_close') if last else 'authorized_simulation_anchor',
           'opening':opening,'purchases':{},'sold':{},'waste':{},'closing':{}}
    if iso == p['effective_from'] and not last:
        record = copy.deepcopy(p['initial_day_record'])
        if record['inventory']['opening'] != opening:raise EngineError('BUSINESS_ANCHOR_INVENTORY_MISMATCH')
    else:
        # ±10% demand around the already +25% reference; no compounded population/growth multiplier.
        demand_pct = _deterministic_range('BUSINESS_DEMAND_V1|'+rule['business_id']+'|'+iso,90,110)
        sales = cogs = purchases = 0
        cash_budget=max(0,_account_units(state,rule['account_id'],'copper')-_account_reserved(state,rule['account_id'],'copper')-p['minimum_cash_reserve_copper']-sum(rule['fixed_costs'].values())-p['other_daily_cash_expenses_copper'])
        purchase_budget=min(p['daily_purchase_limit_copper'],p['daily_cash_debit_limit_copper']-sum(rule['fixed_costs'].values())-p['other_daily_cash_expenses_copper'],cash_budget)
        for sku, m in p['model'].items():
            qty = (m['base_daily_demand']*demand_pct+50)//100
            buy = 0
            if m['purchase_batch'] and opening[sku]-qty <= m['reorder_threshold']:
                need = max(0,m['target_stock']-opening[sku])
                buy = ((need+m['purchase_batch']-1)//m['purchase_batch'])*m['purchase_batch']
            if buy and m['unit_cost_copper']:
                affordable=max(0,purchase_budget-purchases)//m['unit_cost_copper']
                buy=min(buy,(affordable//m['purchase_batch'])*m['purchase_batch'])
            if buy and m.get('supply_status') != 'modeled_available':raise EngineError('BUSINESS_SUPPLY_REQUIRES_REVIEW:'+sku)
            qty = min(qty,opening[sku]+buy)
            # Deterministic small food spoilage is explicit, valued separately from sales COGS.
            waste = min(max(0,opening[sku]+buy-qty), _deterministic_range('BUSINESS_WASTE_V1|'+iso+'|'+sku,0,1)) if m.get('perishable') else 0
            inv['purchases'][sku]=buy;inv['sold'][sku]=qty;inv['waste'][sku]=waste
            inv['closing'][sku]=opening[sku]+buy-qty-waste
            sales+=qty*m['unit_price_copper'];cogs+=qty*m['unit_cost_copper'];purchases+=buy*m['unit_cost_copper']
        record={'scheduled_at':iso,'record_kind':'commander_accepted_simulation',
                'source_refs':[p['source_ref'],'policy:'+p['policy_id'],'model:bounded_demand_v1','previous_simulated_close:'+last],
                'cash_receipts_copper':sales,'cash_purchases_copper':purchases,'other_cash_expenses_copper':p['other_daily_cash_expenses_copper'],
                'gross_sales_copper':sales,'cogs_copper':cogs,'inventory':inv}
    _business_validate_day(record)
    _business_model_check(record,p)
    return {'record':record,'record_sha256':_repair_digest(record),'rule_sha256':_repair_digest(rule),
            'authorization_evidence':{'kind':'standing_simulation_policy','policy_id':p['policy_id'],'policy_sha256':_repair_digest(p),
                'grant_event_id':p['grant_event_id'],'source_ref':p['source_ref'],'record_kind':'commander_accepted_simulation',
                'physical_receipts_confirmed':False,'inventory_physical_stocktake':False},
            'command_id':'SIMINPUT-'+_repair_digest([rule['business_id'],iso])[:24],'recorded_at':iso}


def _business_model_check(record, p):
    inv=record['inventory'];model=p['model']
    if any(set(inv[k]) != set(model) for k in ('opening','purchases','sold','waste','closing')):raise EngineError('BUSINESS_MODEL_SKU_COVERAGE')
    totals={field:sum(inv[k][sku]*m[cost] for sku,m in model.items()) for field,k,cost in (
        ('gross_sales_copper','sold','unit_price_copper'),('cogs_copper','sold','unit_cost_copper'),('cash_purchases_copper','purchases','unit_cost_copper'))}
    if any(record[k] != v for k,v in totals.items()):raise EngineError('BUSINESS_MODEL_AMOUNT_MISMATCH')
    if record['cash_receipts_copper'] != record['gross_sales_copper']:raise EngineError('BUSINESS_MODEL_RECEIVABLE_NOT_AUTHORIZED')
    if record['gross_sales_copper']>p['daily_revenue_limit_copper'] or record['cash_purchases_copper']>p['daily_purchase_limit_copper'] or sum(inv['sold'].values())>p['daily_units_limit']:
        raise EngineError('BUSINESS_DAILY_SCOPE_EXCEEDED')
    if record['other_cash_expenses_copper'] != p['other_daily_cash_expenses_copper']:raise EngineError('BUSINESS_OTHER_EXPENSE_SCOPE')


def _business_simulation_assessment(state,task,iso,saved):
    rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);p=_business_policy(state,task,iso)
    record=_business_validate_day(saved['record']);inv=record['inventory'];_business_model_check(record,p)
    if record['record_kind']!='commander_accepted_simulation' or inv['status']!='continuous_simulated':raise EngineError('BUSINESS_SIMULATION_CLASS')
    if saved != _business_autonomous_input(state,task,iso):raise EngineError('BUSINESS_SIMULATION_INPUT_NOT_REPRODUCIBLE')
    expected=row['inventory'] if row.get('last_settled_at') else p['opening_simulated_inventory']
    if inv['opening']!=expected:raise EngineError('BUSINESS_OPENING_STOCK_MISMATCH')
    fixed=sum(rule['fixed_costs'].values());prepaid,contracts=_business_prepaid_expense(state,rule,iso)
    debit=record['cash_purchases_copper']+record['other_cash_expenses_copper']+fixed
    if debit>p['daily_cash_debit_limit_copper']:raise EngineError('BUSINESS_DAILY_DEBIT_SCOPE_EXCEEDED')
    delta=record['cash_receipts_copper']-debit
    available=_account_units(state,rule['account_id'],'copper')-_account_reserved(state,rule['account_id'],'copper')
    # Reserve must cover outgoing obligations before assuming today's modeled sales.
    if available<debit+p['minimum_cash_reserve_copper'] or available+delta<p['minimum_cash_reserve_copper']:
        return {'status':'INSUFFICIENT_FUNDS','missing':['cash_reserve'],'scheduled_at':iso,'cash_debits_copper':debit}
    waste=sum(inv['waste'][sku]*m['unit_cost_copper'] for sku,m in p['model'].items())
    return {'status':'READY','scheduled_at':iso,'cash_delta_copper':delta,'cash_debits_copper':debit,'fixed_costs_copper':fixed,
        'prepaid_expense_copper':prepaid,'prepaid_contracts':contracts,'inventory_loss_copper':waste,
        'profit_copper':record['gross_sales_copper']-record['cogs_copper']-record['other_cash_expenses_copper']-fixed-prepaid-waste,
        'record_sha256':saved['record_sha256'],'rule_sha256':saved['rule_sha256']}


def _business_assessment(state,task,iso):
    try:
        rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);saved=row['inputs'].get(iso)
        if not row.get('autonomy_policy') or saved and saved.get('authorization_evidence',{}).get('kind')!='standing_simulation_policy':
            return _BUSINESS_V1_ASSESS(state,task,iso)
        saved=saved or _business_autonomous_input(state,task,iso)
        return _business_simulation_assessment(state,task,iso,saved)
    except Exception as ex:return {'status':'INVALID','missing':[str(ex)],'scheduled_at':iso}


def _business_journal(record,check,policy):
    lines=[]
    def post(debit,credit,amount):
        if type(amount) is not int or amount<0:raise EngineError('BUSINESS_JOURNAL_EXACT_INTEGER')
        if amount:lines.extend([{'account':debit,'debit_copper':amount,'credit_copper':0},{'account':credit,'debit_copper':0,'credit_copper':amount}])
    post('shop_cash','sales_revenue',record['cash_receipts_copper'])
    post('simulated_inventory_asset','shop_cash',record['cash_purchases_copper'])
    post('cost_of_goods_sold','simulated_inventory_asset',record['cogs_copper'])
    post('other_operating_expense','shop_cash',record['other_cash_expenses_copper'])
    rule_costs=policy['fixed_costs']
    for key,amount in rule_costs.items():post(key+'_expense','shop_cash',amount)
    post('inventory_loss_expense','simulated_inventory_asset',check['inventory_loss_copper'])
    # Contract was paid by covert funds historically: allocation is a noncash donated benefit.
    post('prepaid_contract_expense','externally_prepaid_benefit_allocation',check['prepaid_expense_copper'])
    model=policy['model'];inv=record['inventory']
    values={k:sum(inv[k][sku]*m['unit_cost_copper'] for sku,m in model.items()) for k in ('opening','purchases','sold','waste','closing')}
    if values['opening']+values['purchases']-values['sold']-values['waste']!=values['closing']:raise EngineError('BUSINESS_INVENTORY_VALUE_EQUATION')
    if sum(x['debit_copper']-x['credit_copper'] for x in lines)!=0:raise EngineError('BUSINESS_JOURNAL_UNBALANCED')
    return {'schema':'BUSINESS_JOURNAL_V1','currency':'copper','evidence_class':'commander_accepted_simulation',
        'physical_receipts_confirmed':False,'lines':lines,'inventory_values_copper':values,
        'cash_delta_copper':check['cash_delta_copper'],'profit_copper':check['profit_copper'],
        'procurement_expensed_twice':False,'prepaid_cash_paid_today_copper':0,'cross_account_cash_transfer_copper':0}


def _business_autonomous_resolve(stage,state,tasks,task,when):
    rule=_business_rule(task);row=_business_runtime(state,rule['business_id']);iso=when.isoformat()
    if not row.get('autonomy_policy'):return _BUSINESS_V1_RESOLVE(stage,state,tasks,task,when)
    prior=row['settlements'].get(iso)
    if prior:
        saved=row['inputs'].get(iso)
        if not saved or saved['record_sha256']!=prior['record_sha256'] or prior['rule_sha256']!=_repair_digest(rule):raise EngineError('BUSINESS_SETTLED_INPUT_CONFLICT')
        return {**copy.deepcopy(prior),'status':'ALREADY_APPLIED'}
    if state['game_time']!=iso or _task_monitor(tasks,task).get('next_review_at')!=iso:raise EngineError('BUSINESS_SETTLEMENT_TIME_MISMATCH')
    check=_business_assessment(state,task,iso)
    if check['status']!='READY':return {'status':'AI_REQUIRED','task_id':task['task_id'],'semantic_barrier':{'kind':'business_reconciliation','assessment':check}}
    saved=row['inputs'].get(iso)
    if saved and saved['authorization_evidence']['kind']!='standing_simulation_policy':return _BUSINESS_V1_RESOLVE(stage,state,tasks,task,when)
    saved=saved or _business_autonomous_input(state,task,iso)
    row['inputs'][iso]=copy.deepcopy(saved)
    _append_engine_history(stage/'events.jsonl',{'event_id':saved['command_id'],'command_id':saved['command_id'],'game_time':iso,
        'type':'system','subtype':'autonomous_simulation_input','summary':'依据长期授权生成正式模拟经营输入；不代表真实POS或实物盘点。',
        'source':'GAME ENGINE standing simulation policy','authority_files':['state.json'],
        'changes':[{'target':'state:engine_runtime.business_runtime_v1','action':'register_simulation_with_provenance'}],
        'simulation_input':copy.deepcopy(saved),'authorization_kind':'standing_simulation_policy'})
    return _BUSINESS_V1_RESOLVE(stage,state,tasks,task,when)


def _resolver_business_daily(stage,state,tasks,task,when):
    before=copy.deepcopy(state);before_tasks=copy.deepcopy(tasks)
    try:
        with _history_append_batch(stage/'events.jsonl'):
            return _business_autonomous_resolve(stage,state,tasks,task,when)
    except BaseException:
        state.clear();state.update(before);tasks.clear();tasks.update(before_tasks);raise


def _business_confirmed_input_history(base,saved):
    ev=history_lookup(base,command_id=saved['command_id'])
    if not ev or ev.get('domain_kind')!='business_day_record' or ev.get('authorization',{}).get('status')!='verified' or ev.get('authorization',{}).get('authority')!='host_intent' or ev.get('authorization',{}).get('evidence_ref')!=saved['authorization_evidence'].get('evidence_ref') or ev.get('domain_effect',{}).get('record_sha256')!=saved['record_sha256'] or ev.get('domain_effect',{}).get('rule_sha256')!=saved['rule_sha256']:
        raise EngineError('BUSINESS_INPUT_HISTORY_MISSING')
    return ev


def business_stocktake_comparison(state,task,record):
    """Compare a trusted actual stocktake with the simulation; old unresolved differences remain open."""
    _business_validate_day(record)
    if record['record_kind']!='actual' or record['inventory']['status']!='confirmed' or record['inventory']['opening_basis']!='stocktake':raise EngineError('BUSINESS_REAL_STOCKTAKE_REQUIRED')
    row=_business_runtime(state,_business_rule(task)['business_id']);opening=record['inventory']['opening'];old=row['inventory']
    return {'schema':'BUSINESS_STOCKTAKE_RECONCILIATION_V1','at':record['scheduled_at'],'previous_inventory_status':row['inventory_status'],
        'previous_book_quantities':copy.deepcopy(old),'confirmed_opening_quantities':copy.deepcopy(opening),
        'difference_quantities':{sku:opening.get(sku,0)-old.get(sku,0) for sku in sorted(set(old)|set(opening))},
        'historical_discrepancies_preserved':True,'cash_adjustment_copper':0,
        'valuation_difference_status':'unvalued_until_explicit_cost_evidence','source_refs':copy.deepcopy(record['source_refs'])}


def _business_policy_source_copy_proof(base,parent,old_state,new_state,new_events):
    """Narrow migration evidence for copied model prices. This never authorizes new market prices."""
    oldrows=old_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    newrows=new_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    covered=set()
    for bid,row in newrows.items():
        if not row.get('autonomy_policy') or oldrows.get(bid,{}).get('autonomy_policy'):continue
        if bid!='YUHUO':raise EngineError('BUSINESS_NEW_MODEL_REQUIRES_EXPLICIT_MIGRATION_SOURCE')
        if old_state['game_time']!=new_state['game_time']:raise EngineError('BUSINESS_GRANT_MUST_BE_ZERO_TIME')
        task=_task_by_id(read_json(Path(parent)/'tasks.json'),row['task_id']);p=_business_policy(new_state,task,old_state['game_time'])
        draft=get_by_path(old_state,'world_state_overrides.freeport_xilu9_current.hawke_commercial_cover.yu_huo_draft_close_83631210')
        grant=[ev for ev in new_events if ev.get('event_id')==p['grant_event_id']]
        if len(grant)!=1 or grant[0].get('authority_kind')!='explicit_commander_upgrade_instruction' or grant[0].get('simulation_policy_sha256')!=_repair_digest(p) or grant[0].get('cash_changed') is not False:raise EngineError('BUSINESS_POLICY_INSTALLATION_PROVENANCE')
        if p['fixed_costs']!=_business_rule(task)['fixed_costs']:raise EngineError('BUSINESS_POLICY_INHERITED_WAGES')
        rec=p['initial_day_record']
        for field in ('gross_sales_copper','cogs_copper','cash_purchases_copper','other_cash_expenses_copper','scheduled_at'):
            if rec[field]!=draft[field]:raise EngineError('BUSINESS_POLICY_DRAFT_SOURCE_MISMATCH')
        if rec['cash_receipts_copper']!=draft['gross_sales_copper']:raise EngineError('BUSINESS_POLICY_SIMULATED_RECEIPTS_SOURCE')
        mapping=['food','repair','trial','candy','water','air','fuel','medical','parts','cable']
        if set(p['model'])!=set(mapping):raise EngineError('BUSINESS_POLICY_INHERITED_MODEL_COVERAGE')
        sold_mapping=['food','repair','trial','water','air','parts','cable']
        for sku,source in zip(sold_mapping,draft['sales_items']):
            model=p['model'][sku]
            if model['unit_cost_copper']*source['sold']!=source['cogs_copper'] or model['unit_price_copper']*source['sold']!=source['sales_copper'] or model['base_daily_demand']!=source['sold']:raise EngineError('BUSINESS_POLICY_PRICE_NOT_SOURCE_COPY:'+sku)
        for sku in ('candy','fuel','medical'):
            if any(p['model'][sku][key]!=0 for key in ('unit_cost_copper','unit_price_copper','base_daily_demand','purchase_batch')):raise EngineError('BUSINESS_UNKNOWN_RESERVE_PRICE_INVENTED')
        for i,sku in enumerate(mapping):
            for field,dfield in (('opening','opening'),('purchases','purchased'),('sold','sold'),('closing','closing')):
                if rec['inventory'][field][sku]!=draft['category_stocktake_simulation'][i][dfield]:raise EngineError('BUSINESS_POLICY_ANCHOR_SOURCE')
        _business_autonomous_input(new_state,task,p['effective_from'])
        prefix='state:engine_runtime.business_runtime_v1.businesses.'+bid+'.autonomy_policy.'
        covered.update(prefix+'model.'+sku+'.'+key for sku in mapping for key in ('unit_cost_copper','unit_price_copper'))
        covered.update(prefix+'fixed_costs.'+key for key in p['fixed_costs'])
    return covered


def _business_settlement_proofs(base,parent,old_state,new_state,new_events):
    """Replay authorized model inputs from parent; verify cash and double-entry journal exactly."""
    old_rows=old_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    new_rows=new_state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    if not any(r.get('autonomy_policy') for r in old_rows.values()):
        proofs,covered=_BUSINESS_V1_PROOFS(base,parent,old_state,new_state,new_events)
        covered.update(_business_policy_source_copy_proof(base,parent,old_state,new_state,new_events))
        return proofs,covered
    tasks=read_json(Path(parent)/'tasks.json');proofs={};covered=set()
    for bid,row in new_rows.items():
        previous=old_rows.get(bid,{})
        if not previous.get('autonomy_policy'):
            if row!=previous:raise EngineError('BUSINESS_UNRELATED_ROW_CHANGED')
            continue
        for key in ('autonomy_policy','autonomy_policy_sha256','historical_gaps','historical_inventory_discrepancies','capital_financing_review'):
            if row.get(key)!=previous.get(key):raise EngineError('BUSINESS_POLICY_OR_HISTORY_IMMUTABLE:'+key)
        for iso,saved in previous['inputs'].items():
            if row['inputs'].get(iso)!=saved:raise EngineError('BUSINESS_CONFIRMED_INPUT_IMMUTABLE')
        for iso,rec in previous['settlements'].items():
            if row['settlements'].get(iso)!=rec:raise EngineError('BUSINESS_OLD_RECEIPT_IMMUTABLE')
        fresh=sorted((iso,r) for iso,r in row['settlements'].items() if iso not in previous['settlements'])
        working=copy.deepcopy(old_state);task=_task_by_id(tasks,row['task_id']);wr=_business_runtime(working,bid)
        for iso,rec in fresh:
            parent_saved=previous['inputs'].get(iso)
            actual=bool(parent_saved and parent_saved['record']['record_kind']=='actual')
            saved=copy.deepcopy(parent_saved) if actual else _business_autonomous_input(working,task,iso)
            if actual:_business_confirmed_input_history(parent,saved)
            if row['inputs'].get(iso)!=saved:raise EngineError('BUSINESS_RECEIPT_NO_VALID_PARENT_INPUT')
            ins=[ev for ev in new_events if ev.get('event_id')==saved['command_id']]
            evs=[ev for ev in new_events if ev.get('event_id')==rec['event_id']]
            if (not actual and (len(ins)!=1 or ins[0].get('simulation_input')!=saved)) or len(evs)!=1 or evs[0].get('business_settlement')!=rec:raise EngineError('BUSINESS_EVENT_RECEIPT_MISMATCH')
            check=_BUSINESS_V1_ASSESS(working,task,iso) if actual else _business_simulation_assessment(working,task,iso,saved)
            if check['status']!='READY' or rec.get('status')!='COMPLETE':raise EngineError('BUSINESS_PARENT_NOT_READY')
            for key,value in check.items():
                if key!='status' and rec.get(key)!=value:raise EngineError('BUSINESS_RECEIPT_RECOMPUTE_MISMATCH:'+key)
            if actual:
                if rec.get('inventory_status')!='confirmed' or rec.get('stocktake_reconciliation')!=business_stocktake_comparison(working,task,saved['record']):raise EngineError('BUSINESS_ACTUAL_STOCKTAKE_RECEIPT')
            elif rec.get('accounting_journal')!=_business_journal(saved['record'],check,wr['autonomy_policy']) or rec.get('inventory_movements')!=saved['record']['inventory'] or rec.get('inventory_status')!='continuous_simulated' or rec.get('physical_receipts_confirmed') is not False:raise EngineError('BUSINESS_JOURNAL_OR_EVIDENCE_MISMATCH')
            rule=_business_rule(task);before=_account_units(working,rule['account_id'],'copper')
            expected_eid='BUSINESS-'+sha256_bytes((bid+'|'+iso+'|daily_close').encode())[:24]
            if rec.get('business_id')!=bid or rec.get('task_id')!=task['task_id'] or rec.get('account_id')!=rule['account_id'] or rec.get('event_id')!=expected_eid or rec.get('cash_before_copper')!=before or rec.get('cash_after_copper')!=before+check['cash_delta_copper']:raise EngineError('BUSINESS_RECEIPT_SUBJECT_OR_CASH')
            for key in ('cash_receipts_copper','cash_purchases_copper','other_cash_expenses_copper','gross_sales_copper','cogs_copper','record_kind','source_refs'):
                if rec.get(key)!=saved['record'][key]:raise EngineError('BUSINESS_RECEIPT_INPUT_AMOUNTS')
            cash=[x for x in _account_registry(new_state)['ledger'] if x['entry_id']==rec['cash_entry_id']]
            if len(cash)!=1 or cash[0]['command_id']!=expected_eid or cash[0]['account_id']!=rule['account_id'] or cash[0]['currency']!='copper' or cash[0]['delta_units']!=check['cash_delta_copper'] or cash[0]['game_time']!=iso:raise EngineError('BUSINESS_CASH_SOURCE_MISMATCH')
            proofs[cash[0]['entry_id']]=cash[0]
            prefix='state:engine_runtime.business_runtime_v1.businesses.'+bid+'.settlements.'+iso
            covered.add(prefix+'.fixed_costs_copper');covered.update(prefix+'.fixed_cost_items.'+k for k in rule['fixed_costs'])
            _account_post(working,rule['account_id'],'copper',check['cash_delta_copper'])
            wr['inventory']=copy.deepcopy(saved['record']['inventory']['closing']);wr['inventory_status']=saved['record']['inventory']['status'];wr['last_settled_at']=iso
        if fresh and (row['inventory']!=wr['inventory'] or row['last_settled_at']!=wr['last_settled_at'] or row['inventory_status']!=wr['inventory_status']):raise EngineError('BUSINESS_FINAL_INVENTORY_MISMATCH')
        for iso in set(row['inputs'])-set(previous['inputs'])-{at for at,_ in fresh}:
            saved=row['inputs'][iso]
            if saved['record']['record_kind']!='actual' or iso!=_task_monitor(read_json(Path(base)/'tasks.json'),_task_by_id(read_json(Path(base)/'tasks.json'),row['task_id'])).get('next_review_at'):raise EngineError('BUSINESS_UNSETTLED_OR_FUTURE_AUTOMATIC_INPUT')
            _business_confirmed_input_history(base,saved)
    return proofs,covered


def business_integrity_report(state,tasks,base=None):
    rows=state.get('engine_runtime',{}).get('business_runtime_v1',{}).get('businesses',{})
    if not any(row.get('autonomy_policy') for row in rows.values()):return _BUSINESS_V1_INTEGRITY(state,tasks,base)
    errors=[]
    try:
        for bid,row in rows.items():
            task=_task_by_id(tasks,row['task_id']);rule=_business_rule(task)
            if not row.get('autonomy_policy'):continue
            p=_business_policy(state,task,rule['effective_from'],enforce_operating=False)
            if base is not None:
                grant=history_lookup(base,event_id=p['grant_event_id'])
                if not grant or grant.get('simulation_policy_sha256')!=_repair_digest(p) or grant.get('authority_kind')!='explicit_commander_upgrade_instruction':raise EngineError('BUSINESS_POLICY_GRANT_HISTORY_MISSING')
            working=copy.deepcopy(state);wr=_business_runtime(working,bid)
            wr['inventory']=copy.deepcopy(p['opening_simulated_inventory']);wr['last_settled_at']=None;wr['inventory_status']='unknown';wr['risk_flags']=[]
            expected_cash=None
            for iso,rec in sorted(row['settlements'].items()):
                _account_record(working,rule['account_id'])['balances']['copper']=rec['cash_before_copper']
                stored=row['inputs'].get(iso);actual=bool(stored and stored['record']['record_kind']=='actual')
                saved=copy.deepcopy(stored) if actual else _business_autonomous_input(working,task,iso)
                if saved!=row['inputs'].get(iso):raise EngineError('BUSINESS_INPUT_NOT_REPRODUCIBLE')
                if expected_cash is not None and rec['cash_before_copper']!=expected_cash:raise EngineError('BUSINESS_CASH_SEQUENCE')
                check_state=copy.deepcopy(working);_account_record(check_state,rule['account_id'])['balances']['copper']=rec['cash_before_copper']
                check=_BUSINESS_V1_ASSESS(check_state,task,iso) if actual else _business_simulation_assessment(check_state,task,iso,saved)
                if check['status']!='READY' or any(rec.get(k)!=v for k,v in check.items() if k!='status'):raise EngineError('BUSINESS_SETTLEMENT_RECOMPUTE')
                if actual:
                    _business_validate_day(saved['record'])
                    if rec.get('inventory_status')!='confirmed' or rec.get('stocktake_reconciliation')!=business_stocktake_comparison(working,task,saved['record']):raise EngineError('BUSINESS_ACTUAL_STOCKTAKE_RECEIPT')
                elif rec.get('accounting_journal')!=_business_journal(saved['record'],check,p) or rec.get('inventory_movements')!=saved['record']['inventory'] or rec.get('inventory_status')!='continuous_simulated' or rec.get('record_kind')!='commander_accepted_simulation' or rec.get('physical_receipts_confirmed') is not False:raise EngineError('BUSINESS_JOURNAL_OR_INVENTORY_CLASS')
                if rec['cash_after_copper']-rec['cash_before_copper']!=rec['cash_delta_copper']:raise EngineError('BUSINESS_CASH_EQUATION')
                cash=[x for x in _account_registry(state)['ledger'] if x['entry_id']==rec['cash_entry_id']]
                if len(cash)!=1 or cash[0]['delta_units']!=rec['cash_delta_copper'] or cash[0]['before_units']!=rec['cash_before_copper'] or cash[0]['after_units']!=rec['cash_after_copper'] or cash[0]['account_id']!=rule['account_id'] or cash[0]['currency']!='copper':raise EngineError('BUSINESS_CASH_RECEIPT_MISSING')
                if base is not None:
                    ev=history_lookup(base,event_id=rec['event_id']);inp=history_lookup(base,event_id=saved['command_id'])
                    if actual:_business_confirmed_input_history(base,saved)
                    if not ev or ev.get('business_settlement')!=rec or (not actual and (not inp or inp.get('simulation_input')!=saved)):raise EngineError('BUSINESS_INPUT_OR_EVENT_HISTORY_MISSING')
                wr['inventory']=copy.deepcopy(saved['record']['inventory']['closing']);wr['last_settled_at']=iso;wr['inventory_status']=saved['record']['inventory']['status']
                expected_cash=rec['cash_after_copper']
            for iso in set(row['inputs'])-set(row['settlements']):
                saved=row['inputs'][iso]
                if saved['record']['record_kind']!='actual' or iso!=_task_monitor(tasks,task).get('next_review_at') or iso>state['game_time']:raise EngineError('BUSINESS_UNSETTLED_OR_FUTURE_AUTOMATIC_INPUT')
                _business_validate_day(saved['record'])
                if saved['record_sha256']!=_repair_digest(saved['record']) or saved['rule_sha256']!=_repair_digest(rule):raise EngineError('BUSINESS_ACTUAL_INPUT_BINDING')
                if base is not None:_business_confirmed_input_history(base,saved)
            if row['last_settled_at']!=wr['last_settled_at'] or (row['settlements'] and (row['inventory']!=wr['inventory'] or row['inventory_status']!=wr['inventory_status'])):raise EngineError('BUSINESS_INVENTORY_CONTINUITY')
    except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors,'evidence_classes':['historical_confirmed','commander_accepted_simulation','unconfirmed_draft'], 'physical_inventory_never_inferred':True}


