    return {'status':'FAIL' if errors else 'PASS','errors':errors,'root':str(base),'engine_version':ENGINE_VERSION,'engine_protocol':ENGINE_PROTOCOL,'guard_version':BUNDLED_GUARD_VERSION,'guard_protocol':GUARD_PROTOCOL}


