_batch_b_query_batch=query_batch_packet
# === VOYAGER_DEV_MODULE: accounts_games ===
_account_command_scope=contextvars.ContextVar('voyager_account_command',default=None)


def _account_registry(state):
    reg=state.get('engine_runtime',{}).get('account_registry_v1')
    if not isinstance(reg,dict) or reg.get('schema')!='ACCOUNT_REGISTRY_V1':raise EngineError('ACCOUNT_REGISTRY_REQUIRED')
    return reg


def _account_record(state,account_id):
    rec=_account_registry(state)['accounts'].get(account_id)
    if not isinstance(rec,dict):raise EngineError('ACCOUNT_NOT_FOUND:'+str(account_id))
    return rec


def _account_units(state,account_id,currency):
    rec=_account_record(state,account_id)
    if currency not in rec['currencies']:raise EngineError('ACCOUNT_CURRENCY_MISMATCH')
    if rec.get('balance_ref'):value=get_by_path(state,rec['balance_ref'])[currency]
    else:value=rec['balances'][currency]
    if type(value) is not int or value<0:raise EngineError('ACCOUNT_UNITS_INVALID')
    return value


def _account_reserved(state,account_id,currency):
    games=state.get('engine_runtime',{}).get('minigame_runtime_v1',{}).get('sessions',{})
    return sum(r['stake_units'] for r in games.values() if r.get('account_id')==account_id and r.get('currency')==currency and r.get('status') in ('reserved','played'))


def _account_sync_views(state,account_id):
    rec=_account_record(state,account_id)
    for view in rec.get('legacy_read_only_views',[]):
        units=_account_units(state,account_id,view['currency']);scale=view.get('units_per_value',1)
        if view.get('available_only'):units-=_account_reserved(state,account_id,view['currency'])
        value=Decimal(units)/Decimal(scale)
        if view.get('format')=='integer':value=int(value)
        elif view.get('format')=='decimal_text':value=_account_decimal_text(units,scale)
        else:
            text=_price_text(value);number=float(text);value=number if Decimal(str(number))==value else text
        parent,key=_dot_parent(state,view['path']);parent[key]=value


def _accounts_record_cash(state,account_id,currency,delta,before,after):
    if type(delta) is not int or after!=before+delta:raise EngineError('ACCOUNT_LEDGER_DELTA_INVALID')
    reg=_account_registry(state);rows=reg['ledger'];seq=len(rows)+1
    row={'seq':seq,'account_id':account_id,'currency':currency,'delta_units':delta,'before_units':before,'after_units':after,
         'game_time':state['game_time'],'command_id':_account_command_scope.get() or 'SYSTEM:engine_credit','source':'current_engine_transaction'}
    row['entry_id']='CASH-'+_repair_digest(row)[:24];rows.append(row)
    return row


def _account_post(state,account_id,currency,delta):
    if type(delta) is not int:raise EngineError('ACCOUNT_INTEGER_DELTA_REQUIRED')
    rec=_account_record(state,account_id)
    if rec.get('status')!='active':raise EngineError('ACCOUNT_CLOSED')
    scale=rec.get('units_per_currency',{}).get(currency)
    quantum=scale//100 if currency=='grey' and type(scale) is int and scale>=100 else 1
    if currency=='grey' and (scale!=MONEY_SCALE or delta%quantum):raise EngineError('ACCOUNT_GREY_QUANTUM_OR_SCALE')
    before=_account_units(state,account_id,currency);after=before+delta
    if after<0:raise EngineError('ACCOUNT_INSUFFICIENT_BALANCE')
    if delta<0 and after<_account_reserved(state,account_id,currency):raise EngineError('ACCOUNT_RESERVED_FUNDS')
    if rec.get('balance_ref'):
        entry=_finance_credit(state,currency,_account_decimal_text(delta,scale))
    else:
        rec['balances'][currency]=after;entry=_accounts_record_cash(state,account_id,currency,delta,before,after)
        _account_sync_views(state,account_id)
    return entry


def _five_account_balances(state):
    specs=(('main_gold','fleet','gold'),('main_grey','fleet','grey'),('covert_copper','covert','copper'),('covert_grey','covert','grey'),('shop_copper','shop','copper'))
    result={}
    for key,aid,cur in specs:
        rec=_account_record(state,aid)
        if cur not in rec.get('currencies',[]):
            result[key]={'status':'NOT_REGISTERED','account_id':aid,'currency':cur,'amount':None};continue
        units=_account_units(state,aid,cur);scale=rec['units_per_currency'][cur]
        result[key]={'status':'CONFIRMED_CURRENT','account_id':aid,'currency':cur,'amount':_account_decimal_text(units,scale),'integer_units':str(units),'units_per_currency':scale,'reserved_units':str(_account_reserved(state,aid,cur))}
        evidence=_business_balance_evidence(state,aid)
        if evidence:
            result[key]['balance_evidence']=evidence
            if evidence['contains_authorized_simulation']:result[key]['status']='ACCEPTED_SIMULATED_BOOK_BALANCE'
        if cur=='copper':result[key]['display']={'gold':units//10000,'silver':units%10000//100,'copper':units%100}
    return result


def _account_transfer_amount(payload):
    cur=payload.get('currency');amount=payload.get('amount')
    if cur not in ('gold','grey','copper') or not isinstance(amount,(str,int)) or isinstance(amount,bool):raise EngineError('ACCOUNT_TRANSFER_EXACT_AMOUNT_REQUIRED')
    scale=1 if cur=='copper' else MONEY_SCALE;raw=_price_decimal(amount)*scale
    if raw!=raw.to_integral_value() or raw<=0:raise EngineError('ACCOUNT_TRANSFER_QUANTUM')
    units=int(raw)
    if cur=='grey' and units%100:raise EngineError('ACCOUNT_GREY_QUANTUM_OR_SCALE')
    return cur,units,scale


def _account_transfer_apply(state,payload):
    cur,units,scale=_account_transfer_amount(payload);src=payload['source_account'];dst=payload['destination_account']
    if src==dst:raise EngineError('ACCOUNT_TRANSFER_SAME_ACCOUNT')
    for aid in (src,dst):
        rec=_account_record(state,aid)
        if cur not in rec.get('currencies',[]) or rec.get('units_per_currency',{}).get(cur)!=scale:raise EngineError('ACCOUNT_TRANSFER_CURRENCY_OR_SCALE_MISMATCH')
        if rec.get('status')!='active':raise EngineError('ACCOUNT_CLOSED')
    if _account_units(state,src,cur)-_account_reserved(state,src,cur)<units:raise EngineError('ACCOUNT_INSUFFICIENT_AVAILABLE_BALANCE')
    debit=_account_post(state,src,cur,-units);credit=_account_post(state,dst,cur,units)
    return {'kind':'account_transfer','currency':cur,'amount':_account_decimal_text(units,scale),'source_account':src,'destination_account':dst,'cash_receipts':[debit,credit],'income_created':False,'entries':[x for aid,x in ((src,debit),(dst,credit)) if aid=='fleet'],'changes':[{'target':'state:engine_runtime.account_registry_v1','action':'internal_transfer_not_operating_income'}]+([{'target':'state:engine_runtime.finance_runtime','action':'transfer_main_account_units'},{'target':'state:summary.funds','action':'derive_main_account_balance'}] if 'fleet' in (src,dst) else [])+[{'target':'state:'+v['path'],'action':'derive_account_view'} for aid in (src,dst) for v in _account_record(state,aid).get('legacy_read_only_views',[])]}


def account_query_packet(base:Path=ROOT,account_id:Optional[str]=None):
    ensure_source_ready(base);state=read_json_view(Path(base)/'state.json');reg=_account_registry(state);rows=[]
    for aid,rec in reg['accounts'].items():
        if account_id and aid!=account_id:continue
        balances={}
        for cur in rec['currencies']:
            units=_account_units(state,aid,cur);reserved=_account_reserved(state,aid,cur);scale=rec['units_per_currency'][cur]
            balances[cur]={'integer_units':str(units),'amount':_account_decimal_text(units,scale),'reserved_units':str(reserved),'available_units':str(units-reserved),'units_per_currency':scale}
        rows.append({'account_id':aid,'status':rec['status'],'owner':copy.deepcopy(rec['owner']),'balance_evidence':_business_balance_evidence(state,aid),'balances':balances,'authority':rec.get('balance_ref') or 'state:engine_runtime.account_registry_v1.accounts.'+aid+'.balances'})
    return {'packet':'ACCOUNT_QUERY_V1','status':'COMPLETE' if rows else 'NOT_FOUND','accounts':rows,'five_balances':_five_account_balances(state) if account_id is None else None,'save_set_id':read_json_view(Path(base)/'manifest.json')['save_set_id']}


def accounts_integrity_report(state):
    reg=state.get('engine_runtime',{}).get('account_registry_v1')
    if reg is None:return {'status':'LEGACY','errors':[]}
    errors=[]
    try:
        _account_registry(state);last={}
        for i,row in enumerate(reg['ledger'],1):
            key=(row['account_id'],row['currency'])
            body={k:v for k,v in row.items() if k!='entry_id'}
            if row.get('entry_id')!='CASH-'+_repair_digest(body)[:24]:errors.append('LEDGER_RECEIPT_HASH')
            if key not in last and row['before_units']!=reg.get('opening_units',{}).get(row['account_id'],{}).get(row['currency']):errors.append('LEDGER_OPENING_BALANCE')
            if row['seq']!=i or row['after_units']!=row['before_units']+row['delta_units']:errors.append('LEDGER_SEQUENCE_OR_AMOUNT')
            if key in last and row['before_units']!=last[key]:errors.append('LEDGER_CHAIN')
            last[key]=row['after_units']
        for aid,rec in reg['accounts'].items():
            if len(rec['currencies'])!=len(set(rec['currencies'])):errors.append('ACCOUNT_DUPLICATE_CURRENCY:'+aid)
            for cur in rec['currencies']:
                units=_account_units(state,aid,cur)
                scale=rec.get('units_per_currency',{}).get(cur)
                if type(scale) is not int or scale<=0 or (cur=='grey' and (scale!=MONEY_SCALE or units%100)):errors.append('ACCOUNT_CURRENCY_SCALE_OR_QUANTUM:'+aid)
                if _account_reserved(state,aid,cur)>units:errors.append('RESERVATION_EXCEEDS_BALANCE:'+aid)
                expected=last.get((aid,cur),reg.get('opening_units',{}).get(aid,{}).get(cur))
                if units!=expected:errors.append('LEDGER_BALANCE:'+aid)
            for view in rec.get('legacy_read_only_views',[]):
                actual=_price_decimal(get_by_path(state,view['path']))*view.get('units_per_value',1)
                if actual!=_account_units(state,aid,view['currency'])-(_account_reserved(state,aid,view['currency']) if view.get('available_only') else 0):errors.append('ACCOUNT_LEGACY_VIEW:'+view['path'])
        for sid,game in state.get('engine_runtime',{}).get('minigame_runtime_v1',{}).get('sessions',{}).items():
            if game.get('status') not in ('reserved','played','settled','cancelled') or game.get('session_id')!=sid or type(game.get('stake_units')) is not int or game['stake_units']<=0:errors.append('GAME_STATE:'+sid)
            if game.get('status') in ('played','settled'):
                expected=_game_result(state,game)
                if game.get('result')!=expected:errors.append('GAME_RESULT:'+sid)
    except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors}


def _game_result(state,session):
    seed=state['engine_runtime']['seed_anchor'];basis=[seed,'coinflip_v1',session['session_id'],session['reserve_command_id']]
    outcome='heads' if int(_repair_digest(basis),16)%2==0 else 'tails'
    payout=session['stake_units']*2 if outcome==session['choice'] else 0
    return {'outcome':outcome,'payout_units':payout,'proof':_repair_digest({'basis_sha256':_repair_digest(basis),'outcome':outcome,'payout_units':payout})}


def _game_session_apply(state,tasks,payload):
    sid=payload['session_id'];action=payload['game_action'];aid=payload['account_id'];currency=payload['currency']
    if not isinstance(sid,str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,100}',sid):raise EngineError('GAME_SESSION_ID_INVALID')
    rt=state['engine_runtime']['minigame_runtime_v1'];sessions=rt['sessions'];rec=sessions.get(sid);entries=[]
    _account_units(state,aid,currency)
    if action=='reserve':
        if rec is not None:raise EngineError('GAME_SESSION_ALREADY_EXISTS')
        stake=payload.get('stake_units');choice=payload.get('choice')
        if type(stake) is not int or stake<=0 or choice not in ('heads','tails'):raise EngineError('GAME_RESERVATION_INVALID')
        if currency=='grey' and stake%100:raise EngineError('GAME_GREY_QUANTUM')
        if _account_record(state,aid)['status']!='active' or stake>_account_units(state,aid,currency)-_account_reserved(state,aid,currency):raise EngineError('GAME_INSUFFICIENT_AVAILABLE_FUNDS')
        sessions[sid]={'session_id':sid,'rule_id':'MINIGAME-COINFLIP-V1','account_id':aid,'currency':currency,'stake_units':stake,'choice':choice,'status':'reserved','reserve_command_id':payload['command_id'],'reserved_at':state['game_time']}
        rec=sessions[sid]
    else:
        if not isinstance(rec,dict) or rec['account_id']!=aid or rec['currency']!=currency:raise EngineError('GAME_SESSION_ACCOUNT_MISMATCH')
        if action=='play':
            if rec['status']!='reserved':raise EngineError('GAME_PLAY_TRANSITION')
            rec.update(status='played',result=_game_result(state,rec),play_command_id=payload['command_id'])
        elif action=='settle':
            if rec['status']!='played':raise EngineError('GAME_SETTLE_TRANSITION')
            if rec['result']!=_game_result(state,rec):raise EngineError('GAME_RESULT_TAMPERED')
            delta=rec['result']['payout_units']-rec['stake_units']
            rec['status']='settled'
            try:entry=_account_post(state,aid,currency,delta)
            except BaseException:
                rec['status']='played';raise
            if aid=='fleet':entries.append(entry)
            rec.update(status='settled',settle_command_id=payload['command_id'],settled_at=state['game_time'],delta_units=delta)
        elif action=='cancel':
            if rec['status']!='reserved':raise EngineError('GAME_CANCEL_TRANSITION')
            rec.update(status='cancelled',cancel_command_id=payload['command_id'])
        else:raise EngineError('GAME_ACTION_INVALID')
    _account_sync_views(state,aid)
    return {'kind':'game_session','session':copy.deepcopy(rec),'entries':entries,'changes':[{'target':'state:engine_runtime.minigame_runtime_v1.sessions.'+sid,'action':action},{'target':'state:engine_runtime.account_registry_v1','action':'atomic_account_receipt'}]}


def _batch_b_command_targets(payload):
    kind=payload.get('kind')
    if kind=='account_transfer':
        cur,_,_=_account_transfer_amount(payload)
        return ['state:account:'+str(payload[k])+':'+cur for k in ('source_account','destination_account')]
    if kind=='business_day_record':
        return ['tasks:task:'+str(payload['task_id']),'state:engine_runtime.business_runtime_v1','state:account:'+str(payload['account_id'])+':copper']
    if kind=='game_session':return ['state:engine_runtime.minigame_runtime_v1.sessions.'+str(payload['session_id']),'state:account:'+str(payload['account_id'])+':'+str(payload['currency'])]
    if kind=='settle_price' and payload.get('delivery'):
        return [_pricing_account_target(payload),'state:engine_runtime.pricing_runtime.settlements.'+str(payload['settlement_id']),payload['delivery']['inventory_ref']]
    if kind=='content_install':return ['catalog:content_packages_v1.packages.'+str(payload['package'].get('package_id'))]
    return None


def _batch_b_command_cost(payload):
    if payload.get('kind')=='account_transfer':
        cur,units,_=_account_transfer_amount(payload)
        return {'uses':1,'gold_units':units if cur in ('gold','copper') else 0,'grey_units':units if cur=='grey' else 0,'quantity':units}
    if payload.get('kind')=='business_day_record':
        debit=_business_integer(payload.get('cash_debit_limit_copper'),'cash_debit_limit_copper')
        return {'uses':1,'gold_units':debit,'grey_units':0,'quantity':1}
    if payload.get('kind')!='game_session':return None
    out={'uses':1,'gold_units':0,'grey_units':0,'quantity':0}
    if payload['game_action']=='reserve':
        stake=payload.get('stake_units')
        if type(stake) is not int or stake<=0:raise EngineError('GAME_INTEGER_STAKE_REQUIRED')
        out['quantity']=stake
        if payload['currency'] in ('gold','grey'):out[payload['currency']+'_units']=stake
        elif payload['currency']=='copper':out['gold_units']=stake
    return out


def _batch_b_apply_command(stage,state,tasks,payload,implementation):
    token=_account_command_scope.set(payload['command_id'])
    try:
        if payload['kind']=='game_session':return _game_session_apply(state,tasks,payload)
        if payload['kind']=='content_install':return _content_install(stage,payload)
        if payload['kind']=='account_transfer':return _account_transfer_apply(state,payload)
        if payload['kind']=='business_day_record':return _business_day_record(state,tasks,payload)
        return implementation(stage,state,tasks,payload)
    finally:_account_command_scope.reset(token)


def _settlement_inventory_delivery(state,quote,payload,confirmed):
    tx=quote['request']['transaction_type']
    if tx not in ('purchase','sale','liquidation'):return []
    delivery=payload.get('delivery')
    if not isinstance(delivery,dict) or delivery!=confirmed.get('inventory_delivery'):raise EngineError('SETTLEMENT_MATCHING_DELIVERY_REQUIRED')
    item=quote['request'].get('item_id');routes={'SUPPLY-FOOD':'food','SUPPLY-WATER':'water','SUPPLY-PARTS':'maintenance_parts','SUPPLY-AIR':'compressed_air','SUPPLY-FUEL':'fuel','SUPPLY-MEDICAL':'medical_kits'}
    ref=delivery.get('inventory_ref','');prefix='state:inventories.supply_inventory.fleets.'
    if item not in routes or not ref.startswith(prefix):raise EngineError('SETTLEMENT_TYPED_INVENTORY_ROUTE_REQUIRED')
    tail=ref[len(prefix):].split('.')
    if len(tail)!=3 or tail[0] not in ('voyager','jinchuan') or tail[1]!=routes[item] or tail[2]!='value':raise EngineError('SETTLEMENT_ITEM_INVENTORY_MISMATCH')
    qty=_price_decimal(quote['quantity']);delta=qty if tx=='purchase' else -qty
    if delta!=delta.to_integral_value() or _price_decimal(delivery.get('delta'))!=delta:raise EngineError('SETTLEMENT_QUANTITY_MISMATCH')
    leaf=get_by_path(state,ref[6:].rsplit('.',1)[0])
    if delivery.get('unit')!=leaf['unit'] or quote['unit']!=leaf['unit']:raise EngineError('SETTLEMENT_DELIVERY_UNIT_MISMATCH')
    before=leaf['value'];after=before+int(delta)
    if type(before) is not int or after<0:raise EngineError('SETTLEMENT_INVENTORY_BALANCE_INVALID')
    leaf['value']=after
    return [{'target':ref,'action':'verified_atomic_inventory_delivery','before':before,'after':after,'source_event_id':payload['source_event_id']}]


def _account_decimal_text(units,scale):
    if type(units) is not int or scale not in (1,10,100,1000,10000):raise EngineError('ACCOUNT_EXACT_UNITS_REQUIRED')
    whole,frac=divmod(abs(units),scale);sign='-' if units<0 else ''
    return sign+str(whole)+('.'+str(frac).zfill(len(str(scale))-1).rstrip('0') if frac else '')

_batch_b_account_query=account_query_packet
# === VOYAGER_DEV_MODULE: snapshot_service ===
_snapshot_scope=contextvars.ContextVar('voyager_snapshot_context',default=None)


def _derived_key(base):
    path=Path(base)/'.runtime'/'derived_cache.key';path.parent.mkdir(parents=True,exist_ok=True)
    if path.is_symlink():raise EngineError('CACHE_KEY_PATH_INVALID')
    if not path.exists():
        # Readers share the source lock: publish a fully written inode atomically,
        # never expose the empty O_EXCL file to another initializing reader.
        fd,name=tempfile.mkstemp(prefix='.derived_cache.key.',dir=path.parent);tmp=Path(name)
        try:
            with os.fdopen(fd,'wb') as stream:stream.write(os.urandom(32));stream.flush();os.fsync(stream.fileno())
            try:os.link(tmp,path);_native_sync_dir(path.parent)
            except FileExistsError:pass
        finally:tmp.unlink(missing_ok=True)
    if path.is_symlink():raise EngineError('CACHE_KEY_PATH_INVALID')
    key=path.read_bytes()
    if len(key)!=32:raise EngineError('CACHE_KEY_INVALID')
    return key


def _derived_read(base,name,binding):
    import hmac
    if os.environ.get('VOYAGER_DISABLE_DERIVED_CACHE')=='1':return None
    path=Path(base)/'.runtime'/name
    if not path.is_file() or path.is_symlink():return None
    try:
        wrapper=json.loads(path.read_text('utf-8'));body=wrapper['body'];keypath=Path(base)/'.runtime'/'derived_cache.key'
        if not keypath.is_file() or keypath.is_symlink():return None
        key=keypath.read_bytes()
        if len(key)!=32:return None
        expected=hmac.new(key,json.dumps(body,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode(),'sha256').hexdigest()
        if not hmac.compare_digest(expected,wrapper['mac']) or body.get('binding')!=binding:return None
        return body['value']
    except Exception:return None


def _derived_write(base,name,binding,value):
    import hmac
    if os.environ.get('VOYAGER_DISABLE_DERIVED_CACHE')=='1':return
    body={'binding':binding,'value':value}
    try:
        mac=hmac.new(_derived_key(base),json.dumps(body,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode(),'sha256').hexdigest()
        _native_atomic_json(Path(base)/'.runtime'/name,{'body':body,'mac':mac})
    except (OSError,EngineError):return False  # Optional derived data must not block healthy authority.
    return True


class SnapshotContext:
    """One cooperative shared lock and one verified byte set per read request.
    Cached semantics are keyed by actual hashes and authenticated locally; every
    request still hashes every declared archive and checks active recovery intent.
    """
    def __init__(self,base):
        self.base=Path(base).resolve();self.json={};self.views={};self.histories={};self.report=None;self.authority=None
        self.metrics={'json_parses':0,'history_decodes':0,'sha_calls':0,'bytes_hashed':0,'semantic_cache_hits':0,'full_semantic_checks':0,'history_index_incremental':0}
    def __enter__(self):
        existing=_snapshot_scope.get()
        if existing and existing.base==self.base:self.reused=existing;return existing
        self.reused=None;self.lock=engine_lock(self.base,exclusive=False);self.lock.__enter__();self.token=_snapshot_scope.set(self)
        try:
            manifest_bytes=(self.base/'manifest.json').read_bytes();self.manifest=strict_json_loads(manifest_bytes.decode('utf-8'))
            names=['manifest.json',*self.manifest.get('components',{}),*_component_cold_archives(self.manifest)]
            if (self.base/'development').exists():names+=list(self.manifest.get('development_sources',{}).get('files',{}))
            self.fingerprint={n:_snapshot_file_fingerprint(self.base/n) for n in dict.fromkeys(names)}
            if sha256_bytes(manifest_bytes)!=self.fingerprint['manifest.json']:raise EngineError('SNAPSHOT_MANIFEST_READ_NOT_BOUND')
            self.layout=self.boundary_layout()
            self.binding={'schema':'SNAPSHOT_SEMANTICS_V3','engine_version':ENGINE_VERSION,'fingerprint':self.fingerprint,'layout':self.layout}
            self.json['manifest.json']=self.manifest
            return self
        except BaseException:_snapshot_scope.reset(self.token);self.lock.__exit__(*sys.exc_info());raise
    def __exit__(self,*exc):
        if self.reused:return False
        try:
            if exc[0] is None:
                after={n:_snapshot_file_fingerprint(self.base/n) for n in self.fingerprint}
                if after!=self.fingerprint or self.boundary_layout()!=self.layout:raise EngineError('SNAPSHOT_CHANGED_DURING_READ')
                if any(_active_runtime_journal(self.base,n) for n in (NATIVE_COMMIT_JOURNAL_FILENAME,CONSISTENCY_REPAIR_JOURNAL)):raise EngineError('RECOVERY_INTENT_DURING_READ')
        finally:_snapshot_scope.reset(self.token);self.lock.__exit__(*exc)
    def boundary_layout(self):
        # Build lexical ancestors once. lstat and directory shape are still read
        # at BOTH boundaries; no mtime/stat tuple substitutes for content hashes.
        if not hasattr(self,'layout_paths'):
            paths={}
            for name in self.fingerprint:
                parts=Path(name).parts
                if not parts or Path(name).is_absolute() or '..' in parts:raise EngineError('SNAPSHOT_PATH_INVALID')
                for i in range(1,len(parts)+1):
                    rel=str(Path(*parts[:i]));paths[rel]=self.base/rel
            self.layout_paths=sorted(paths.items())
        rows=[]
        for rel,path in self.layout_paths:
            try:mode=path.lstat().st_mode
            except OSError:mode=None
            rows.append([rel,mode,stat.S_ISLNK(mode) if mode is not None else False])
        shape=sorted([p.name,p.is_file(),p.is_dir(),p.is_symlink()] for p in self.base.iterdir() if not p.name.startswith('.'))
        return {'paths':rows,'shape':shape}

    def _read_value(self,path):
        name=path.name
        if path.parent!=self.base:return _batch_b_strict_json(path)
        if name not in self.json:
            data=path.read_bytes()
            if name in self.fingerprint and sha256_bytes(data)!=self.fingerprint[name]:raise EngineError('SNAPSHOT_READ_BYTES_NOT_BOUND')
            self.metrics['json_parses']+=1;self.json[name]=strict_json_loads(data.decode('utf-8'))
        return self.json[name]
    def read(self,path):
        path=Path(path).resolve();self.metrics['json_mutable_copies']=self.metrics.get('json_mutable_copies',0)+1
        if path.name=='state.json':self.metrics['state_mutable_copies']=self.metrics.get('state_mutable_copies',0)+1
        return copy.deepcopy(self._read_value(path))
    def read_view(self,path):
        path=Path(path).resolve();value=self._read_value(path)
        if path.parent!=self.base:return _stage2_freeze(value)
        if path.name not in self.views:
            self.views[path.name]=_stage2_freeze(value);self.metrics['json_view_builds']=self.metrics.get('json_view_builds',0)+1
        return self.views[path.name]
    def validated_report(self):
        if self.report is not None:return copy.deepcopy(self.report)
        for name in (NATIVE_COMMIT_JOURNAL_FILENAME,CONSISTENCY_REPAIR_JOURNAL):
            if _active_runtime_journal(self.base,name):
                self.report=_batch_b_readiness(self.base);return copy.deepcopy(self.report)
        if any(v is None for v in self.fingerprint.values()):
            self.metrics['full_semantic_checks']+=1;self.report=_batch_b_readiness(self.base);return copy.deepcopy(self.report)
        value=_derived_read(self.base,'read_semantics_v2.json',self.binding)
        if value is not None:
            self.report=value;self.metrics['semantic_cache_hits']+=1
        else:
            self.metrics['full_semantic_checks']+=1;self.report=_batch_b_readiness(self.base)
            if self.report['status']!='BLOCKED':_derived_write(self.base,'read_semantics_v2.json',self.binding,self.report)
        if self.report['status']!='BLOCKED':self.authority=_snapshot_authority(self.base,self.manifest,self.fingerprint)
        return copy.deepcopy(self.report)


def _snapshot_authority(base,manifest,fingerprint):
    ver=parse_version(manifest['save_version']);data=manifest['authority_components'];bundle=manifest['authority_bundle_sha256']
    index={'version':ver,'save_set_id':manifest['save_set_id'],'parent_save_set_id':manifest.get('parent_save_set_id'),'engine_version':manifest['engine_version'],'engine_sha256':manifest['tool_bindings']['engine.py'],'save_guard_sha256':manifest['tool_bindings']['guard.py'],'hashes':data,'bundle':bundle}
    return {'base':base,'version':ver,'bundle':bundle,'save_set_id':manifest['save_set_id'],'manifest':data,'index':index,'index_sha256':fingerprint['manifest.json'],'component_manifest':manifest}


def _snapshot_file_fingerprint(path):
    try:return _snapshot_sha_file(path)
    except OSError:return None  # Absence/unreadability is a blocking validation input.


def _snapshot_sha_file(path):
    ctx=_stage2_cache_owner()
    if ctx:
        ctx.metrics['sha_calls']=ctx.metrics.get('sha_calls',0)+1
        try:ctx.metrics['bytes_hashed']=ctx.metrics.get('bytes_hashed',0)+Path(path).stat().st_size
        except OSError:pass
    return _batch_b_sha_file(path)


def _snapshot_json_read(path):
    ctx=_snapshot_scope.get();path=Path(path).resolve()
    return ctx.read(path) if ctx and path.parent==ctx.base and path.suffix=='.json' else _batch_b_strict_json(path)


def _snapshot_history_read(path,validate_metadata=True):
    if _stage2_memo() is None:return _batch_b_history_read(Path(path),validate_metadata)
    _stage2_count('history_full_copies')
    return copy.deepcopy(_stage2_history_value(path,validate_metadata))


def _snapshot_epoch_decode(rec,lineno=0,base=None,_archive_bytes=None):
    return _stage2_epoch_value(rec,lineno,base,_archive_bytes)


def _snapshot_readiness(base=ROOT):
    ctx=_snapshot_scope.get()
    if ctx and Path(base).resolve()==ctx.base:return ctx.validated_report()
    try:
        with SnapshotContext(base) as snapshot:return snapshot.validated_report()
    except (OSError,json.JSONDecodeError):return _batch_b_readiness(Path(base).resolve())


def _snapshot_validate_authority(base):
    ctx=_snapshot_scope.get()
    if ctx and Path(base).resolve()==ctx.base and ctx.authority is not None:return copy.deepcopy(ctx.authority)
    return _batch_b_validate_authority(base)


def _history_locator_binding(base):
    m=strict_json_load(Path(base)/'manifest.json')
    return {'schema':'HISTORY_LOCATORS_V2','engine':sha256_file(Path(base)/'engine.py'),'history':sha256_file(Path(base)/'events.jsonl'),'cold':{n:r['file_sha256'] for n,r in _component_cold_archives(m).items() if 'seq_start' in r}}


def history_locator_index(base):
    base=Path(base).resolve();binding=_history_locator_binding(base);cached=_derived_read(base,'history_locator_v2.json',binding)
    if cached is not None:return cached
    data=(base/'events.jsonl').read_bytes();rows=data.splitlines(keepends=True);body=b''.join(rows[1:]);prior=_derived_read(base,'history_locator_incremental.json',{'engine':binding['engine'],'cold':binding['cold']})
    locators={};commands={};offset=0;start_line=0;last_seq=0
    if prior and len(body)>=prior['body_bytes'] and sha256_bytes(body[:prior['body_bytes']])==prior['body_sha256']:
        locators=copy.deepcopy(prior['events']);commands=prior['commands'];last_seq=prior['last_seq'];start_line=prior['physical_lines'];offset=sum(len(x) for x in rows[:start_line]);ctx=_snapshot_scope.get()
        shift=len(rows[0])-prior['header_bytes']
        for loc in locators.values():
            if 'offset' in loc:loc['offset']+=shift
        if ctx:ctx.metrics['history_index_incremental']+=1
    for i,raw in enumerate(rows):
        if i<start_line:continue
        if not raw.strip():offset+=len(raw);continue
        rec=strict_json_loads(raw.decode())
        if rec.get('record_type')=='metadata':offset+=len(raw);continue
        if rec.get('record_type')=='history_epoch':
            events,raws=_decode_history_epoch_record(rec,i+1,base)
            pairs=[(ev,{'epoch':copy.deepcopy(rec),'index':j,'raw_sha256':sha256_bytes(eraw)}) for j,(ev,eraw) in enumerate(zip(events,raws))]
        else:pairs=[(rec,{'offset':offset,'length':len(raw),'raw_sha256':sha256_bytes(raw.rstrip(b'\r\n'))})]
        for ev,loc in pairs:
            if ev.get('seq')!=last_seq+1 or ev.get('event_id') in locators:raise EngineError('HISTORY_LOCATOR_SEQUENCE')
            last_seq=ev['seq'];locators[ev['event_id']]=loc
            if ev.get('command_id'):
                # A transaction may also contain a changeset; authoritative command
                # receipts are the unique domain commit event, not the audit diff.
                if ev.get('subtype')=='domain_command_commit':
                    if ev['command_id'] in commands:raise EngineError('HISTORY_COMMAND_RECEIPT_DUPLICATE')
                    commands[ev['command_id']]=ev['event_id']
        offset+=len(raw)
    meta=strict_json_loads(rows[0].decode())
    if meta['next_seq']!=last_seq+1:raise EngineError('HISTORY_LOCATOR_METADATA_TAIL')
    index={'header_bytes':len(rows[0]),'events':locators,'commands':commands,'last_seq':last_seq,'body_bytes':len(body),'body_sha256':sha256_bytes(body),'physical_lines':len(rows)}
    _derived_write(base,'history_locator_v2.json',binding,index)
    _derived_write(base,'history_locator_incremental.json',{'engine':binding['engine'],'cold':binding['cold']},index)
    return index


def history_lookup(base,event_id=None,command_id=None):
    base=Path(base).resolve();index=history_locator_index(base)
    if command_id:event_id=index['commands'].get(command_id)
    loc=index['events'].get(event_id)
    if loc is None:return None
    if 'epoch' in loc:
        events,raws=_decode_history_epoch_record(loc['epoch'],0,base);raw=raws[loc['index']];ev=events[loc['index']]
    else:
        with (base/'events.jsonl').open('rb') as stream:stream.seek(loc['offset']);raw=stream.read(loc['length']).rstrip(b'\r\n')
        ev=strict_json_loads(raw.decode())
    if sha256_bytes(raw)!=loc['raw_sha256'] or ev.get('event_id')!=event_id:raise EngineError('HISTORY_LOCATOR_PAYLOAD_CHANGED')
    return ev


def read_json_view(path):
    """Internal immutable ownership; a matching snapshot remains mandatory."""
    path=Path(path).resolve();ctx=_snapshot_scope.get()
    if not ctx or ctx.base!=path.parent:return _stage2_freeze(_batch_b_strict_json(path))
    return ctx.read_view(path)
# === VOYAGER_DEV_MODULE: memory_content ===
CONTENT_UNITS={'艘','人','台','架','支','枚','包','桶','箱','罐','kg','t','吨','米','m','份','晚','gold','grey','copper','silver','%','hour','day','dimensionless'}
CONTENT_KINDS={'organization','location','equipment','scene_family','semantic_rule','random_tables'}


def validate_content_package(package,installed):
    if not isinstance(package,dict) or (package.get('schema')!='VOYAGER_CONTENT_PACKAGE_V1' or (type(package.get('schema_version')) is not int or package.get('schema_version')!=1)):raise EngineError('CONTENT_SCHEMA')
    pid=package.get('package_id');namespace=package.get('namespace');version=package.get('version')
    if not isinstance(pid,str) or not re.fullmatch(r'[a-z][a-z0-9_.-]{2,100}',pid) or not isinstance(namespace,str) or not re.fullmatch(r'[a-z][a-z0-9_.-]{2,80}',namespace):raise EngineError('CONTENT_NAMESPACE')
    if not isinstance(version,str) or not re.fullmatch(r'\d+\.\d+\.\d+',version):raise EngineError('CONTENT_VERSION')
    if package.get('rule_version') is None or not package.get('source') or package.get('visibility') not in ('player','gm','definition_only'):raise EngineError('CONTENT_SOURCE_OR_VISIBILITY')
    if pid in installed:raise EngineError('CONTENT_PACKAGE_ALREADY_INSTALLED')
    for dep,wanted in package.get('dependencies',{}).items():
        if dep not in installed or installed[dep]['version']!=wanted:raise EngineError('CONTENT_DEPENDENCY:'+dep)
    used={d['id'] for p in installed.values() for d in p.get('definitions',[])};conflicts={d.get('conflict_key') for p in installed.values() for d in p.get('definitions',[]) if d.get('conflict_key')};seen=set()
    definitions=package.get('definitions')
    if not isinstance(definitions,list) or not definitions:raise EngineError('CONTENT_DEFINITIONS_REQUIRED')
    def data_only(x):
        if isinstance(x,dict):
            for k,v in x.items():
                if k in ('python','code','script','exec','eval','__class__'):raise EngineError('CONTENT_EXECUTABLE_CODE_FORBIDDEN')
                if k=='unit' and v not in CONTENT_UNITS:raise EngineError('CONTENT_UNKNOWN_UNIT:'+str(v))
                if k in ('price','price_gold','unit_price'):raise EngineError('CONTENT_PRICE_REQUIRES_PRICE_REGISTRY')
                data_only(v)
        elif isinstance(x,list):
            for v in x:data_only(v)
        elif isinstance(x,float) and not math.isfinite(x):raise EngineError('CONTENT_NONFINITE_NUMBER')
        elif x is not None and not isinstance(x,(str,int,float,bool)):raise EngineError('CONTENT_NOT_JSON_DATA')
    for row in definitions:
        if not isinstance(row,dict) or row.get('kind') not in CONTENT_KINDS or not isinstance(row.get('id'),str) or not row['id'].startswith(namespace+':'):raise EngineError('CONTENT_DEFINITION_ID_OR_KIND')
        rid=row['id']
        if rid in seen or rid in used:raise EngineError('CONTENT_DUPLICATE_ID:'+rid)
        seen.add(rid)
        if row.get('conflict_key') in conflicts:raise EngineError('CONTENT_RULE_CONFLICT')
        if row.get('conflict_key'):conflicts.add(row['conflict_key'])
        if row.get('kind')=='semantic_rule' and row.get('implementation')!='semantic_only':raise EngineError('CONTENT_RULE_BINDING_REQUIRED')
        if row.get('kind')=='random_tables' and (pid!='voyager.core.random' or row.get('resolver')!='deterministic_hazard_tables_v3'):raise EngineError('CONTENT_MECHANICAL_RESOLVER_UNREGISTERED')
        if row.get('kind')=='equipment' and (not row.get('unit') or row.get('ownership_effect')!='definition_only'):raise EngineError('CONTENT_EQUIPMENT_MUST_BE_DEFINITION_ONLY')
        data_only(row)
    data_only(package)
    return {'status':'PASS','package_id':pid,'definitions':len(definitions),'definition_ids':sorted(seen),'world_instances_created':0}


def _content_install(stage,payload):
    path=Path(stage)/'catalog.json';catalog=read_json(path);registry=catalog.get('content_packages_v1') or {'schema':'CONTENT_PACKAGE_REGISTRY_V1','packages':{}};package=copy.deepcopy(payload['package']);check=validate_content_package(package,registry['packages'])
    registry['packages'][package['package_id']]=package;catalog['content_packages_v1']=registry;_write_authority_json(path,catalog)
    return {'kind':'content_install','validation':check,'changes':[{'target':'catalog:content_packages_v1.packages.'+package['package_id'],'action':'install_data_only_definition_package'}]}


def content_query_packet(base=ROOT,kind=None,topic=None,audience='player'):
    ensure_source_ready(base);registry=read_json_view(Path(base)/'catalog.json').get('content_packages_v1',{});rows=[]
    if audience=='gm' and (os.environ.get('VOYAGER_DEVELOPER_MODE')!='1' or os.environ.get('VOYAGER_DIAGNOSTIC_CONTEXT')!='gm'):raise EngineError('GM_DIAGNOSTIC_CONTEXT_REQUIRED')
    for pid,pack in registry.get('packages',{}).items():
        if audience!='gm' and pack.get('visibility')=='gm':continue
        for row in pack['definitions']:
            if audience!='gm' and row.get('visibility')=='gm':continue
            if kind and row['kind']!=kind:continue
            if topic and topic not in json.dumps(row,ensure_ascii=False):continue
            rows.append({'package_id':pid,'version':pack['version'],'definition':copy.deepcopy(row),'creates_player_asset':False})
    return {'packet':'CONTENT_QUERY_V1','status':'COMPLETE','definitions':rows,'prices':'unknown unless separately registered in price authority'}


def _registered_random_data():
    catalog=read_json(ROOT/'catalog.json');package=catalog.get('content_packages_v1',{}).get('packages',{}).get('voyager.core.random')
    if not package:raise EngineError('CORE_RANDOM_CONTENT_PACKAGE_REQUIRED_EXPLICIT_MIGRATION')
    return copy.deepcopy(next(d['data'] for d in package['definitions'] if d['kind']=='random_tables'))


def content_integrity_report(base):
    errors=[];catalog=read_json(Path(base)/'catalog.json');packages=catalog.get('content_packages_v1',{}).get('packages',{})
    if not packages:return {'status':'LEGACY','errors':[]}
    checked={}
    try:
        # Dependencies are validated against the complete installed set, while the
        # uniqueness/conflict pass accumulates earlier definitions deterministically.
        for pid,p in packages.items():
            deps={k:v for k,v in packages.items() if k!=pid and k not in checked}
            shell={k:{**v,'definitions':[]} for k,v in deps.items()};validate_content_package(p,{**shell,**checked});checked[pid]=p
        random=next(d['data'] for d in packages['voyager.core.random']['definitions'] if d['kind']=='random_tables')
        sealed=read_json(Path(base)/'rules.json')['runtime_rules']
        if set(random)!={'framework','tables'}:errors.append('RANDOM_CONTENT_SCHEMA')
        if sealed.get('random_event_tables')!=random['tables']:errors.append('RANDOM_CONTENT_RULE_BINDING:random_event_tables')
        for key,value in random['framework'].items():
            if sealed.get('random_event_framework',{}).get(key)!=value:errors.append('RANDOM_CONTENT_RULE_BINDING:framework.'+key)
    except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors,'packages':len(packages)}


def memory_read_packet(base,path,audience='player'):
    ensure_source_ready(base);base=Path(base);state=read_json(base/'state.json');registry=state['engine_runtime'].get('memory_layers_v1') or {};entry=registry.get('cold_paths',{}).get(path)
    if not entry:raise EngineError('MEMORY_REFERENCE_NOT_FOUND')
    if audience!='gm':
        return {'packet':'MEMORY_READ_V1','status':'REFERENCE_ONLY','source_path':path,'summary':entry['summary'],'epistemic':'source_summary_not_new_fact','archive_ref':entry['archive_ref'],'full_payload_requires':'gm diagnostic context'}
    if os.environ.get('VOYAGER_DEVELOPER_MODE')!='1' or os.environ.get('VOYAGER_DIAGNOSTIC_CONTEXT')!='gm':raise EngineError('GM_DIAGNOSTIC_CONTEXT_REQUIRED')
    with gzip.open(base/entry['archive_ref'],'rt',encoding='utf-8') as stream:wrapper=json.load(stream)
    payload=wrapper['payload']
    if _repair_digest(payload)!=entry['payload_sha256'] or wrapper['payload_sha256']!=entry['payload_sha256']:raise EngineError('MEMORY_ARCHIVE_HASH')
    value=payload['objects'][path]
    if _repair_digest(value)!=entry['object_sha256']:raise EngineError('MEMORY_OBJECT_HASH')
    return {'packet':'MEMORY_READ_V1','status':'COMPLETE','source_path':path,'value':value,'source_event_ids':entry['source_event_ids'],'archived':True}


def memory_integrity_report(base):
    state=read_json(Path(base)/'state.json');reg=state.get('engine_runtime',{}).get('memory_layers_v1')
    if not reg:return {'status':'LEGACY','errors':[]}
    errors=[]
    for path,entry in reg.get('cold_paths',{}).items():
        try:
            marker=get_by_path(state,path)
            if marker.get('$storage')!='cold_archive' or marker.get('archive_ref')!=entry['archive_ref']:errors.append('MEMORY_REDIRECT:'+path)
            # Actual file hash is checked at the shared authority boundary; payload
            # hashes and exact old values are inspected on explicit retrieval/full audit.
            if not (Path(base)/entry['archive_ref']).is_file():errors.append('MEMORY_ARCHIVE_MISSING:'+path)
        except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors,'cold_objects':len(reg.get('cold_paths',{}))}

