def _story_entity_expected(state):
    out=_batch_c_entity_expected(state)
    for eid,rec in state.get('engine_runtime',{}).get('story_runtime_v1',{}).get('entities',{}).items():
        path='engine_runtime.story_runtime_v1.entities.'+eid
        out[eid]={'entity_type':'person','canonical_name':rec['name'],'aliases':rec.get('aliases',[]),'status':'active','state_path':path,'source_ref':path,'managed_by':'story_runtime_v1'}
    return out


def _story_targets(payload):
    if payload.get('kind') not in ('story_action','story_transaction'):return _batch_c_targets(payload)
    actions=payload.get('actions') if payload['kind']=='story_transaction' else [payload.get('action')]
    if not isinstance(actions,list) or not 1<=len(actions)<=80:raise EngineError('STORY_ACTION_BATCH_INVALID')
    targets=[]
    for action in actions:
        if not isinstance(action,dict) or action.get('type') not in STORY_ACTIONS:raise EngineError('STORY_ACTION_UNKNOWN')
        typ=action['type'];sid=action.get('scene_id')
        if sid:targets.append('state:engine_runtime.scene_registry_v1.records.'+_story_id(sid))
        if typ=='entity_register':targets+=['state:entity_registry','state:engine_runtime.story_runtime_v1.entities.'+_story_id(action.get('entity_id')),'state:engine_runtime.story_turns_v1.npcs.'+_story_id(action.get('entity_id')),'state:engine_runtime.living_world_v1.profiles.'+_story_id(action.get('entity_id'))]
        elif typ.startswith('experience_'):targets.append('events:experience_v1')
        elif typ=='scene_focus':targets.append('state:engine_runtime.story_runtime_v1.focus_scene_id')
        else:targets.append('state:engine_runtime.story_runtime_v1')
        if action.get('task_id')==_PATROL_TASK_ID or (sid and typ=='scene_phase' and action.get('patrol_adapter') is True):targets+=['tasks:task:'+_PATROL_TASK_ID,'state:'+SCENE_PATROL_PATH+'.current_local_event']
    return sorted(set(targets))


def _story_cost(payload):
    if payload.get('kind') in ('story_action','story_transaction'):
        actions=payload.get('actions') if payload['kind']=='story_transaction' else [payload.get('action')]
        return {'uses':1,'gold_units':0,'grey_units':0,'quantity':len(actions) if isinstance(actions,list) else 0}
    return _batch_c_cost(payload)


def _story_actions_apply(stage,state,tasks,payload):
    if payload.get('kind') not in ('story_action','story_transaction'):
        if payload.get('kind')=='scene_record' and payload.get('scene_action')=='create':
            for eid in payload.get('participants',[]):_story_entity(state,eid)
        result=_batch_c_apply(stage,state,tasks,payload)
        if payload.get('kind')=='scene_record' and payload.get('scene_action')=='create':
            rt=_story_runtime(state);tid=payload['task_id'];binding=rt['task_scene_bindings'].setdefault(tid,{'task_id':tid,'one_open_scene':True,'adapter':'patrol_v1' if tid==_PATROL_TASK_ID else 'generic','scene_ids':[]});binding['scene_ids'].append(payload['scene_id'])
        return result
    digest=_domain_payload_digest(payload);ctx={'event_id':'DOMAIN-'+payload['command_id']+'-'+sha256_bytes(str(digest).encode())[:8],'command_id':payload['command_id'],'authorization_ref':payload['authorization_ref'],'outer':payload,'stage':Path(stage)};token=_story_scope.set(ctx)
    try:
        actions=payload['actions'] if payload['kind']=='story_transaction' else [payload['action']];results=[];changes=[]
        for action in actions:
            if action.get('type')=='scene_create':raise EngineError('STORY_LEGACY_SCENE_USE_TYPED_SCENE_OPEN')
            result=_s3_apply_update(stage,state,tasks,copy.deepcopy(action)) if action.get('type')=='entity_register' else _story_action_apply(stage,state,tasks,copy.deepcopy(action));results.append(result);changes+=result.get('changes',[])
        report=_story_integrity(state,tasks)
        if report['status']!='PASS':raise EngineError('STORY_POSTCHECK:'+str(report['errors']))
        return {'kind':payload['kind'],'results':results,'changes':changes}
    finally:_story_scope.reset(token)


def _story_action_apply(stage,state,tasks,action):
    _story_action_schema(action)
    typ=action['type'];rt=_story_runtime(state);ctx=_story_event_context();now=state['game_time'];sid=action.get('scene_id');changes=[];out={'action':typ}
    if typ=='entity_register':
        eid=_story_id(action['entity_id']);name=_story_text(action['name'],100);aliases=action.get('aliases',[])
        if not isinstance(aliases,list) or any(not isinstance(a,str) or not a.strip() for a in aliases):raise EngineError('STORY_ENTITY_ALIASES')
        if eid in state['entity_registry']['entities']:raise EngineError('STORY_ENTITY_ID_EXISTS_USE_REFERENCE')
        names={_normalize_search_text(n) for rec in state['entity_registry']['entities'].values() for n in [rec['canonical_name'],*rec.get('aliases',[])]}
        if any(_normalize_search_text(n) in names for n in [name,*aliases]):raise EngineError('STORY_ENTITY_NAME_EXISTS_USE_REFERENCE')
        rt['entities'][eid]={'entity_id':eid,'name':name,'aliases':aliases,'role':_story_text(action.get('role','independent civilian'),300),'registered_at':now,'source_event_id':ctx['event_id'],'crew_or_asset_created':False};_sync_entity_registry(state);changes=[{'target':'state:engine_runtime.story_runtime_v1.entities.'+eid,'action':'register_stable_person_identity'},{'target':'state:entity_registry','action':'derive_identity_route'}];out['entity_id']=eid
    elif typ=='scene_create':
        tid=action['task_id'];participants=action.get('participants',[])
        for eid in participants:_story_entity(state,eid)
        binding=rt['task_scene_bindings'].setdefault(tid,{'task_id':tid,'one_open_scene':True,'adapter':'patrol_v1' if tid==_PATROL_TASK_ID else 'generic','scene_ids':[]})
        p={'kind':'scene_record','scene_action':'create','scene_id':sid,'task_id':tid,'scene_type':_story_text(action['family'],80),'title':_story_text(action['title'],200),'participants':participants,'facts':[],'command_id':ctx['command_id']}
        effect=_scene_domain_record(state,tasks,p);rec=_story_record(state,sid);rec['knowledge_scope']='explicit';rec['location_label']=_story_text(action.get('location_label','未确认位置'),200);rec['story_schema']='STORY_SCENE_V1';binding['scene_ids'].append(sid);changes=effect['changes']+[{'target':'state:engine_runtime.story_runtime_v1.task_scene_bindings.'+tid,'action':'bind_scene'}];out['scene_id']=sid
    elif typ=='scene_focus':
        if sid is not None:_story_record(state,sid,True)
        rt['focus_scene_id']=sid;changes=[{'target':'state:engine_runtime.story_runtime_v1.focus_scene_id','action':'explicit_focus'}]
    elif typ=='scene_phase':
        rec=_story_record(state,sid,True);p={'scene_id':sid,'scene_action':'close' if action['phase']=='closed' else 'advance','phase':action['phase'],'command_id':ctx['command_id'],'task_id':rec['task_id']}
        if rec['task_id']==_PATROL_TASK_ID and action.get('patrol_adapter') is not True:raise EngineError('STORY_PATROL_TARGET_EXPLICIT_REQUIRED')
        effect=_scene_domain_record(state,tasks,p);changes=effect['changes']
        if action['phase']=='closed' and rt['focus_scene_id']==sid:rt['focus_scene_id']=None;changes.append({'target':'state:engine_runtime.story_runtime_v1.focus_scene_id','action':'release_closed_focus'})
    elif typ in ('fact_append','fact_correct','knowledge_disclose','evidence_link'):
        return _knowledge_action(stage,state,tasks,action)
    elif typ=='decision_open':
        rec=_story_record(state,sid,True);did=_story_id(action['decision_id'])
        if did in rt['decisions']:raise EngineError('STORY_DECISION_EXISTS')
        rt['decisions'][did]={'decision_id':did,'scene_id':sid,'prompt':_story_text(action['prompt']),'status':'pending','source_event_id':ctx['event_id']};rec.setdefault('pending_decisions',[]).append(did);changes=[{'target':'state:engine_runtime.story_runtime_v1.decisions.'+did,'action':'open_decision'},{'target':'state:engine_runtime.scene_registry_v1.records.'+sid+'.pending_decisions','action':'link_decision'}]
    elif typ=='decision_resolve':
        rec=_story_record(state,sid,True);decision=rt['decisions'].get(action['decision_id'])
        if not decision or decision['scene_id']!=sid or decision['status']!='pending':raise EngineError('STORY_DECISION_NOT_PENDING')
        decision.update(status='resolved',player_action=_story_text(action['player_action']),resolved_at=now,cause_event_id=ctx['event_id']);rec['pending_decisions'].remove(action['decision_id']);changes=[{'target':'state:engine_runtime.story_runtime_v1.decisions.'+action['decision_id'],'action':'resolve_freeform_choice'},{'target':'state:engine_runtime.scene_registry_v1.records.'+sid+'.pending_decisions','action':'resolve_decision'}]
    elif typ in ('narrative_commit','narrative_rewrite','consequence_resolve'):return _narrative_action(stage,state,tasks,action)
    elif typ in ('experience_record','experience_revoke'):return _experience_action(stage,state,action)
    else:raise EngineError('STORY_ACTION_UNKNOWN')
    return {**out,'changes':changes}


def _story_integrity(state,tasks):
    errors=[];rt=state.get('engine_runtime',{}).get('story_runtime_v1')
    if not rt:return {'status':'LEGACY','errors':[]}
    try:
        if rt['schema']!='STORY_RUNTIME_V1':errors.append('SCHEMA')
        records=_scene_registry(state)['records'];taskids={r['task_id'] for bucket in ('active_tasks','queued_tasks') for r in tasks.get(bucket,[])}
        focus=rt.get('focus_scene_id')
        if focus is not None and (focus not in records or records[focus]['phase']=='closed'):errors.append('FOCUS')
        for old,binding in rt.get('legacy_viewer_bindings',{}).items():
            if not old.startswith('observer:') or not binding['viewer_id'].startswith('npc:') or not binding.get('source_ref'):errors.append('LEGACY_KNOWLEDGE_IDENTITY_ROUTE')
            _story_entity(state,binding['viewer_id'][4:],False)
        for tid,b in rt['task_scene_bindings'].items():
            if len(set(b['scene_ids']))!=len(b['scene_ids']):errors.append('BINDING_DUPLICATE:'+tid)
            live=[sid for sid in b['scene_ids'] if records[sid]['phase']!='closed']
            if live and tid not in taskids:errors.append('TASK_NOT_LIVE:'+tid)
            if len(live)>1 or any(records[sid]['task_id']!=tid for sid in b['scene_ids']):errors.append('BINDING_CONFLICT:'+tid)
        for rec in records.values():
            if rec.get('story_schema')=='STORY_SCENE_V1':
                for eid in rec.get('participants',[]):_story_entity(state,eid,False)
                if rec['scene_id'] not in rt['task_scene_bindings'][rec['task_id']]['scene_ids']:errors.append('UNBOUND_SCENE')
        for did,d in rt['decisions'].items():
            if d['status']=='pending' and did not in records[d['scene_id']]['pending_decisions']:errors.append('DECISION_LINK')
        errors+=_knowledge_integrity(state);errors+=_narrative_integrity(state)
    except Exception as ex:errors.append(str(ex))
    return {'status':'FAIL' if errors else 'PASS','errors':errors,'bound_tasks':len(rt.get('task_scene_bindings',{})),'registered_people':len(rt.get('entities',{}))}


def _story_action_schema(action):
    keys={
      'entity_register':({'entity_id','name'},{'aliases','role'}),
      'scene_create':({'scene_id','task_id','family','title'},{'participants','location_label'}),
      'scene_phase':({'scene_id','phase'},{'patrol_adapter','task_id'}),
      'scene_focus':({'scene_id'},set()),
      'fact_append':({'scene_id','fact_id','subject_id','predicate','value','epistemic','source_category'},{'confidence_basis'}),
      'fact_correct':({'scene_id','fact_id','subject_id','predicate','value','epistemic','source_category','supersedes_fact_id'},{'confidence_basis'}),
      'knowledge_disclose':({'scene_id','fact_id','viewer_id','channel','basis_event_id'},set()),
      'evidence_link':({'scene_id','fact_id','basis_event_id'},set()),
      'decision_open':({'scene_id','decision_id','prompt'},set()),
      'decision_resolve':({'scene_id','decision_id','player_action'},set()),
      'narrative_commit':({'scene_id','proposal_id','proposal'},set()),
      'narrative_rewrite':({'scene_id','proposal_id','draft_text'},set()),
      'consequence_resolve':({'scene_id','consequence_id','status'},{'reason'}),
      'experience_record':({'entry'},set()),
      'experience_revoke':({'entry_id','reason'},set())}
    if not isinstance(action,dict) or action.get('type') not in keys:raise EngineError('STORY_ACTION_UNKNOWN')
    required,optional=keys[action['type']];fields=set(action)-{'type'}
    if not required<=fields or fields-(required|optional):raise EngineError('STORY_ACTION_SCHEMA:'+action['type'])
# === VOYAGER_DEV_MODULE: knowledge_policy ===
STORY_PREDICATES={'appearance','atmosphere','goal','social_reaction','statement','intent','route_hint'}


def _knowledge_key(sid,fid):return _story_id(sid)+'/'+_story_id(fid)


def _knowledge_index(state):
    owner=_stage2_cache_owner()
    if owner is None or not isinstance(state,_ReadOnlyDict):return None
    if not hasattr(owner,'proofs'):owner.proofs={}
    key=('knowledge_index_v3',id(state))
    if key in owner.proofs:return owner.proofs[key][1]
    facts={};learning={};known={};corrections={};subjects={};disclosures={};legacy_known={};aliases={};rt=_story_runtime(state)
    for old,row in rt.get('legacy_viewer_bindings',{}).items():
        aliases.setdefault(row['viewer_id'],set()).add(old);_stage2_count('knowledge_alias_bindings_indexed')
    for sid,rec in _scene_registry(state)['records'].items():
        facts[sid]={fid:{'fact_id':fid,'scene_id':sid,'value':row.get('value',row.get('text')),'epistemic':row['epistemic'],'valid_from':row.get('valid_from',row.get('as_of',rec.get('created_at'))),'source_event_ids':copy.deepcopy(row.get('source_event_ids',[])),'legacy_record':True,'source_ref':'state:engine_runtime.scene_registry_v1.records.'+sid+'.facts.'+fid} for fid,row in rec.get('facts',{}).items()}
        for position,row in enumerate(rec.get('disclosures',[])):
            viewer=row.get('viewer');fid=row['fact_id']
            disclosures.setdefault((sid,viewer),{}).setdefault(fid,[]).append((position,row))
            legacy_known.setdefault((sid,viewer),set()).add(fid);_stage2_count('knowledge_disclosures_indexed')
    for row in rt['facts'].values():facts.setdefault(row['scene_id'],{})[row['fact_id']]=row
    for row in rt['learning_events']:
        learning.setdefault((row['scene_id'],row['viewer_id'],row['fact_id']),[]).append(row);known.setdefault((row['scene_id'],row['viewer_id']),set()).add(row['fact_id']);_stage2_count('knowledge_learning_indexed')
    for sid,rows in facts.items():
        for row in rows.values():
            subjects.setdefault((sid,row.get('subject_id')),[]).append(row['fact_id'])
            if row.get('supersedes_fact_id'):corrections.setdefault((sid,row['supersedes_fact_id']),[]).append(row['fact_id'])
    value={'facts':facts,'learning':learning,'known':known,'corrections':corrections,'subjects':subjects,'disclosures':disclosures,'legacy_known':legacy_known,'aliases':aliases,'rows':{}}
    owner.proofs[key]=(state,value);_stage2_count('knowledge_index_builds');return value


def _knowledge_facts(state,sid):
    rec=_story_record(state,sid);index=_knowledge_index(state)
    if index is not None:return copy.deepcopy(index['facts'].get(sid,{}))
    facts={}
    for fid,row in rec.get('facts',{}).items():
        facts[fid]={'fact_id':fid,'scene_id':sid,'value':row.get('value',row.get('text')),'epistemic':row['epistemic'],'valid_from':row.get('valid_from',row.get('as_of',rec.get('created_at'))),'source_event_ids':copy.deepcopy(row.get('source_event_ids',[])),'legacy_record':True,'source_ref':'state:engine_runtime.scene_registry_v1.records.'+sid+'.facts.'+fid}
    for key,row in _story_runtime(state)['facts'].items():
        if row['scene_id']==sid:facts[row['fact_id']]=copy.deepcopy(row)
    return facts


def _knowledge_known(state,sid,viewer):
    rec=_story_record(state,sid);index=_knowledge_index(state)
    if index is not None:
        viewers={viewer}
        if viewer.startswith('npc:'):viewers|={'observer:'+viewer[4:]}|index['aliases'].get(viewer,set())
        known=set(index['known'].get((sid,viewer),set()))
        for original in viewers:known.update(index['legacy_known'].get((sid,original),set()))
        return known
    known={d['fact_id'] for d in rec.get('disclosures',[]) if d.get('viewer')==viewer}
    if viewer.startswith('npc:'):
        aliases={'observer:'+viewer[4:]}
        aliases|={old for old,row in _story_runtime(state).get('legacy_viewer_bindings',{}).items() if row['viewer_id']==viewer}
        known|={d['fact_id'] for d in rec.get('disclosures',[]) if d.get('viewer') in aliases}
    known|={r['fact_id'] for r in _story_runtime(state)['learning_events'] if r['scene_id']==sid and r['viewer_id']==viewer}
    return known


def _knowledge_viewer(viewer,diagnostic=False):
    if viewer in ('player','gm'):
        if viewer=='gm' and not diagnostic:raise EngineError('GM_DIAGNOSTIC_CONTEXT_REQUIRED')
        return viewer
    if not isinstance(viewer,str) or not re.fullmatch(r'(observer|npc):[A-Za-z0-9_.:-]{1,100}',viewer):raise EngineError('KNOWLEDGE_VIEWER_INVALID')
    if viewer.startswith('npc:') and not diagnostic:raise EngineError('NPC_PRIVATE_CONTEXT_REQUIRES_GM')
    return viewer


def _knowledge_action(stage,state,tasks,action):
    rt=_story_runtime(state);sid=_story_id(action['scene_id']);rec=_story_record(state,sid);ctx=_story_event_context();typ=action['type'];now=state['game_time'];fid=_story_id(action['fact_id']);key=_knowledge_key(sid,fid);facts=_knowledge_facts(state,sid)
    if typ in ('fact_append','fact_correct'):
        _story_record(state,sid,True)
        if fid in facts:raise EngineError('KNOWLEDGE_FACT_ID_EXISTS')
        subject=action['subject_id'];_story_entity(state,subject,False);predicate=action['predicate']
        if predicate not in STORY_PREDICATES:raise EngineError('KNOWLEDGE_MECHANICAL_FACT_REQUIRES_DOMAIN_COMMAND')
        value=_story_text(action['value']);epistemic=action['epistemic'];source=action.get('source_category')
        if epistemic=='confirmed':_narrative_soft_text(value)
        if epistemic not in ('confirmed','rumor','hypothesis') or source not in ('direct_observation','npc_statement','creative_setting'):raise EngineError('KNOWLEDGE_SOURCE_OR_EPISTEMIC')
        supersedes=action.get('supersedes_fact_id')
        if typ=='fact_correct':
            if supersedes not in facts or facts[supersedes]['epistemic'] not in ('rumor','hypothesis'):raise EngineError('KNOWLEDGE_CORRECTION_REQUIRES_UNCERTAIN_ORIGINAL')
        elif supersedes:raise EngineError('KNOWLEDGE_USE_CORRECTION_ACTION')
        rt['facts'][key]={'fact_id':fid,'scene_id':sid,'subject_id':subject,'predicate':predicate,'value':value,'epistemic':epistemic,'valid_from':now,'valid_to':None,'source_category':source,'confidence_basis':_story_text(action.get('confidence_basis','explicit authorized story commitment'),500),'source_event_ids':[ctx['event_id']],'supersedes_fact_id':supersedes}
        # Facts are private until an explicit, source-backed acquisition action.
        return {'action':typ,'fact_id':fid,'changes':[{'target':'state:engine_runtime.story_runtime_v1.facts.'+key,'action':'append_fact_without_implicit_disclosure'}]}
    if fid not in facts:raise EngineError('KNOWLEDGE_FACT_NOT_FOUND')
    basis=action['basis_event_id'];basis=ctx['event_id'] if basis=='$current_transaction' else basis;event=None
    if basis!=ctx['event_id']:event=history_lookup(stage,event_id=basis)
    if basis!=ctx['event_id'] and not event:raise EngineError('KNOWLEDGE_BASIS_EVENT_MISSING')
    if typ=='evidence_link':
        if rec['phase']=='closed':raise EngineError('KNOWLEDGE_CLOSED_EVIDENCE_IMMUTABLE')
        link={'scene_id':sid,'fact_id':fid,'evidence_event_id':basis,'linked_at':now,'record_event_id':ctx['event_id']}
        if link in rt['evidence_links']:raise EngineError('KNOWLEDGE_EVIDENCE_ALREADY_LINKED')
        rt['evidence_links'].append(link);return {'action':typ,'changes':[{'target':'state:engine_runtime.story_runtime_v1.evidence_links','action':'link_original_event'}]}
    viewer=action['viewer_id'];_knowledge_viewer(viewer,True)
    if viewer=='gm':raise EngineError('KNOWLEDGE_GM_NEEDS_NO_DISCLOSURE')
    if viewer.startswith('npc:'):_story_entity(state,viewer[4:])
    if fid in _knowledge_known(state,sid,viewer):raise EngineError('KNOWLEDGE_ALREADY_KNOWN')
    if rec['phase']=='closed':
        receipts=(event or {}).get('knowledge_disclosures',[])
        if not any(x.get('scene_id')==sid and x.get('fact_id')==fid and x.get('viewer_id')==viewer for x in receipts):raise EngineError('HISTORICAL_DISCLOSURE_EVIDENCE_INSUFFICIENT')
    channel=action.get('channel')
    if channel not in ('observed','heard','reported','document'):raise EngineError('KNOWLEDGE_ACQUISITION_CHANNEL_REQUIRED')
    rt['learning_events'].append({'scene_id':sid,'fact_id':fid,'viewer_id':viewer,'learned_at':now,'channel':channel,'basis_event_id':basis,'record_event_id':ctx['event_id']})
    return {'action':typ,'viewer_id':viewer,'fact_id':fid,'changes':[{'target':'state:engine_runtime.story_runtime_v1.learning_events','action':'record_explicit_knowledge_acquisition'}]}


def _knowledge_rows(state,sid,viewer):
    index=_knowledge_index(state);rec=_story_record(state,sid)
    if index is not None and (sid,viewer) in index['rows']:
        _stage2_count('knowledge_rows_cache_hits');return copy.deepcopy(index['rows'][(sid,viewer)])
    facts=index['facts'].get(sid,{}) if index is not None else _knowledge_facts(state,sid);known=set(facts) if viewer=='gm' else _knowledge_known(state,sid,viewer);rows=[]
    aliases={viewer}
    if viewer.startswith('npc:'):
        aliases|=index['aliases'].get(viewer,set()) if index is not None else {old for old,binding in _story_runtime(state).get('legacy_viewer_bindings',{}).items() if binding['viewer_id']==viewer}
    for fid,row in facts.items():
        if fid not in known:continue
        item=copy.deepcopy(row)
        if index is not None:
            # Preserve physical disclosure order across aliases, including the old
            # distinction between implicit observer knowledge and sourced aliases.
            legacy=sorted((entry for alias in aliases for entry in index['disclosures'].get((sid,alias),{}).get(fid,[])),key=lambda entry:entry[0])
            acquired=[entry[1] for entry in legacy]
        else:acquired=[d for d in rec.get('disclosures',[]) if d.get('viewer') in aliases and d['fact_id']==fid]
        item['acquired_from']=[{'learned_at':d.get('disclosed_at'),'basis':d.get('basis'),'source_ref':'state:engine_runtime.scene_registry_v1.records.'+sid+'.disclosures','original_viewer_id':d['viewer']} for d in acquired]
        item['acquired_from'] += [copy.deepcopy(d) for d in (index['learning'].get((sid,viewer,fid),[]) if index is not None else _story_runtime(state)['learning_events']) if d['scene_id']==sid and d['fact_id']==fid and d['viewer_id']==viewer]
        corrections=[cid for cid in index['corrections'].get((sid,fid),[]) if cid in known] if index is not None else [f['fact_id'] for f in facts.values() if f.get('supersedes_fact_id')==fid and f['fact_id'] in known]
        if corrections:item['superseded_by']=corrections
        if viewer!='gm':item.pop('confidence_basis',None);item.pop('source_category',None)
        rows.append(item)
    if index is not None:index['rows'][(sid,viewer)]=_stage2_freeze(rows);_stage2_count('knowledge_rows_builds')
    return rows


def _story_scene_visible(state,rec,viewer):
    if viewer=='gm':return True
    if rec.get('source_event_id') and viewer in rec.get('visible_to',[]):return True
    if rec.get('knowledge_scope')=='explicit':return bool(_knowledge_known(state,rec['scene_id'],viewer))
    if viewer=='player':return rec['phase']!='proposed'
    return bool(_knowledge_known(state,rec['scene_id'],viewer))


def _story_current_summary(state,viewer='player'):
    rt=_story_runtime(state);records=_scene_registry(state)['records'];live=[r for r in records.values() if r['phase'] not in ('closed','proposed') and _story_scene_visible(state,r,viewer)];focus=rt['focus_scene_id']
    if focus and any(r['scene_id']==focus for r in live):
        r=records[focus];return {'scene_id':focus,'task_id':r['task_id'],'phase':r['phase'],'status':'FOCUSED'}
    return {'scene_id':None,'task_id':None,'phase':None,'status':'FOCUS_REQUIRED' if live else 'NO_OPEN_SCENE','candidates':[{'scene_id':r['scene_id'],'task_id':r['task_id'],'phase':r['phase']} for r in live]}


def _story_scene_query(base,scene_id,audience='player',observer_id=None,gm_context=None):
    viewer=_scene_viewer(audience,observer_id,gm_context)
    with SnapshotContext(base):
        ready=ensure_source_ready(base);state=read_json_view(Path(base)/'state.json');reg=_scene_registry(state);rec=reg['records'].get(scene_id)
        if rec is None:return _batch_c_scene_query(base,scene_id,audience,observer_id,gm_context)
