def knowledge_packet(base,sid,viewer='player'):
    diagnostic=os.environ.get('VOYAGER_DEVELOPER_MODE')=='1' and os.environ.get('VOYAGER_DIAGNOSTIC_CONTEXT')=='gm';viewer=_knowledge_viewer(viewer,diagnostic)
